B.avf=new A.Hb("subhan","\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650","Glory be to Allah",33)
B.ave=new A.Hb("hamd","\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650","All praise is for Allah",33)
B.avd=new A.Hb("akbar","\u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f","Allah is Greatest",33)
B.avg=new A.Hb("istighfar","\u0623\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064e","I seek Allah\u2019s forgiveness",100)
