B.ed=s(["1\u6708","2\u6708","3\u6708","4\u6708","5\u6708","6\u6708","7\u6708","8\u6708","9\u6708","10\u6708","11\u6708","12\u6708"],t.s)
B.bO1=new A.QM("A calendar marker; no act of worship is prescribed for the day",3,"calendar")
B.bO3=new A.kt(1,1,"Islamic New Year","\u0631\u0623\u0633 \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0647\u062c\u0631\u064a\u0629",B.bO1,"The first day of Muharram, the first month of the Hijri year. The Hijri calendar counts years from the Prophet\u2019s \ufdfa migration to Madinah. No special act is prescribed for the day itself; Muharram is a sacred month, and the Prophet \ufdfa called fasting in it the best fasting after Ramadan.","Sahih Muslim 1163")
B.p3=new A.QM("Established in the Qur\u2019an and sunnah",0,"established")
B.bOa=new A.kt(1,10,"Day of Ashura","\u064a\u0648\u0645 \u0639\u0627\u0634\u0648\u0631\u0627\u0621",B.p3,"The Prophet \ufdfa fasted the 10th of Muharram and told the Muslims to fast it; he intended to add the 9th as well. Fasting it expiates the sins of the previous year.","Sahih al-Bukhari 2004 \xb7 Sahih Muslim 1134, 1162")
B.Zl=new A.QM("Scholars differ on observing this day",2,"contested")
B.bO5=new A.kt(3,12,"Mawlid an-Nabi \ufdfa","\u0627\u0644\u0645\u0648\u0644\u062f \u0627\u0644\u0646\u0628\u0648\u064a",B.Zl,"12 Rabi\u02bf al-Awwal is the popular date for the birth of the Prophet \ufdfa; the exact day is itself reported differently. Many Muslims mark it with remembrance and salawat, while other scholars hold that marking a birthday is not part of the religion. Love of the Prophet \ufdfa is shown in following his sunnah and sending salawat on him, which are encouraged every day.","")
B.Zk=new A.QM("The event is established; the date is a popular reckoning",1,"dateUncertain")
B.bO2=new A.kt(7,27,"Isra\u2019 & Mi\u2019raj","\u0627\u0644\u0625\u0633\u0631\u0627\u0621 \u0648\u0627\u0644\u0645\u0639\u0631\u0627\u062c",B.Zk,"The Night Journey from Makkah to al-Aqsa is in the Qur\u2019an. The date is not fixed by an authentic report; 27 Rajab is the popular reckoning, and scholars differ on whether to mark it. The gift of the night was the five daily prayers.","Qur\u2019an 17:1 \xb7 Sahih al-Bukhari 349")
B.bO8=new A.kt(8,15,"Laylat al-Bara\u2019ah","\u0644\u064a\u0644\u0629 \u0627\u0644\u0628\u0631\u0627\u0621\u0629",B.Zl,"The night of 15 Sha\u2018ban is marked in some regions with night prayer and fasting the next day. Scholars differ on whether singling it out has an authentic basis, so this app does not recommend a special practice for it. Fasting the White Days (13\u201315) of every month is established.","")
B.bO7=new A.kt(9,1,"Ramadan Begins","\u0628\u062f\u0627\u064a\u0629 \u0631\u0645\u0636\u0627\u0646",B.p3,"The month of fasting. \u201cWhoever of you witnesses the month, let him fast it.\u201d The month begins with the sighting of the new moon; this app shows the Umm al-Qura calendar date, so confirm by your local sighting.","Qur\u2019an 2:185")
B.bOb=new A.kt(9,27,"Laylat al-Qadr","\u0644\u064a\u0644\u0629 \u0627\u0644\u0642\u062f\u0631",B.Zk,"The Night of Decree, better than a thousand months. Its exact night is not known: the Prophet \ufdfa told us to seek it in the odd nights of the last ten nights of Ramadan. 27 Ramadan is the popular guess and is shown here only as a reminder to seek it on all of them.","Qur\u2019an 97:1\u20133 \xb7 Sahih al-Bukhari 2017")
B.bO6=new A.kt(10,1,"Eid al-Fitr","\u0639\u064a\u062f \u0627\u0644\u0641\u0637\u0631",B.p3,"The festival that ends Ramadan: the Eid prayer, charity (zakat al-fitr) given before the prayer, and food and family. Fasting on this day is prohibited.","Sahih al-Bukhari 1503, 1991 \xb7 Sahih Muslim 1137")
B.bO9=new A.kt(12,9,"Day of Arafah","\u064a\u0648\u0645 \u0639\u0631\u0641\u0629",B.p3,"The day the pilgrims stand at Arafah. For those not on Hajj, fasting it expiates the sins of the previous and the coming year.","Sahih Muslim 1162")
B.bO4=new A.kt(12,10,"Eid al-Adha","\u0639\u064a\u062f \u0627\u0644\u0623\u0636\u062d\u0649",B.p3,"The festival of sacrifice on 10 Dhul-Hijjah: the Eid prayer, then the sacrifice and sharing its meat. Fasting on this day, and on the three days of Tashreeq after it, is prohibited.","Sahih al-Bukhari 1991 \xb7 Sahih Muslim 1137, 1141")
B.bxd=s([B.bO3,B.bOa,B.bO5,B.bO2,B.bO8,B.bO7,B.bOb,B.bO6,B.bO9,B.bO4],A.a6("A<kt>"))
