B.aNh=s(["\u0623\u062f\u0631\u062c \u0633\u0624\u0627\u0644\u064a","\u0645\u06cc\u0631\u0627 \u0633\u0648\u0627\u0644 \u0634\u0627\u0645\u0644 \u06a9\u0631\u06cc\u06ba","\u0986\u09ae\u09be\u09b0 \u09aa\u09cd\u09b0\u09b6\u09cd\u09a8 \u09af\u09c1\u0995\u09cd\u09a4 \u0995\u09b0\u09c1\u09a8"],t.s)
B.bv_=s(["\u0634\u0643\u0631\u064b\u0627 \u0644\u0643. \u0623\u064f\u0631\u0633\u0644 \u0627\u0644\u0628\u0644\u0627\u063a.","\u0634\u06a9\u0631\u06cc\u06c1\u06d4 \u0631\u067e\u0648\u0631\u0679 \u0628\u06be\u06cc\u062c \u062f\u06cc \u06af\u0626\u06cc\u06d4","\u09a7\u09a8\u09cd\u09af\u09ac\u09be\u09a6\u0964 \u09b0\u09bf\u09aa\u09cb\u09b0\u09cd\u099f \u09aa\u09be\u09a0\u09be\u09a8\u09cb \u09b9\u09af\u09bc\u09c7\u099b\u09c7\u0964"],t.s)
B.b3k=s(["\u0634\u0643\u0631\u064b\u0627 \u0644\u0643. \u062d\u064f\u0641\u0638 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632 \u0648\u0633\u064a\u064f\u0631\u0633\u0644 \u0639\u0646\u062f \u0641\u062a\u062d \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0645\u0639 \u0627\u062a\u0635\u0627\u0644 \u0628\u0627\u0644\u0625\u0646\u062a\u0631\u0646\u062a.","\u0634\u06a9\u0631\u06cc\u06c1\u06d4 \u06cc\u06c1 \u0627\u0633 \u0622\u0644\u06d2 \u067e\u0631 \u0645\u062d\u0641\u0648\u0638 \u06c1\u06d2 \u0627\u0648\u0631 \u0627\u06af\u0644\u06cc \u0628\u0627\u0631 \u0627\u0646\u0679\u0631\u0646\u06cc\u0679 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0627\u06cc\u067e \u06a9\u06be\u0648\u0644\u0646\u06d2 \u067e\u0631 \u0628\u06be\u06cc\u062c \u062f\u06cc \u062c\u0627\u0626\u06d2 \u06af\u06cc\u06d4","\u09a7\u09a8\u09cd\u09af\u09ac\u09be\u09a6\u0964 \u098f\u099f\u09bf \u098f\u0987 \u09a1\u09bf\u09ad\u09be\u0987\u09b8\u09c7 \u09b8\u0982\u09b0\u0995\u09cd\u09b7\u09bf\u09a4 \u0986\u099b\u09c7 \u098f\u09ac\u0982 \u09aa\u09b0\u09c7\u09b0 \u09ac\u09be\u09b0 \u09b8\u0982\u09af\u09cb\u0997\u09b8\u09b9 \u0985\u09cd\u09af\u09be\u09aa \u0996\u09c1\u09b2\u09b2\u09c7 \u09aa\u09be\u09a0\u09be\u09a8\u09cb \u09b9\u09ac\u09c7\u0964"],t.s)
B.aP5=s(["\u0623\u0631\u0633\u0644 \u0627\u0644\u0628\u0644\u0627\u063a","\u0631\u067e\u0648\u0631\u0679 \u0628\u06be\u06cc\u062c\u06cc\u06ba","\u09b0\u09bf\u09aa\u09cb\u09b0\u09cd\u099f \u09aa\u09be\u09a0\u09be\u09a8"],t.s)
B.b77=s(["\u062d\u0633\u0627\u0628\u0643 \u0627\u0644\u062e\u0627\u0635 \u0644\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)","\u0622\u067e \u06a9\u0627 \u0627\u067e\u0646\u0627 \u0627\u06d2 \u0622\u0626\u06cc \u0627\u06a9\u0627\u0624\u0646\u0679 (\u0627\u062e\u062a\u06cc\u0627\u0631\u06cc)","\u0986\u09aa\u09a8\u09be\u09b0 \u09a8\u09bf\u099c\u09c7\u09b0 \u098f\u0986\u0987 \u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f (\u0990\u099a\u09cd\u099b\u09bf\u0995)"],t.s)
B.b6W=s(["\u0644\u0627 \u062a\u062d\u062a\u0627\u062c \u0625\u0644\u0649 \u0647\u0630\u0627. \u064a\u062c\u064a\u0628 \u0647\u0627\u062f\u064a \u0623\u0635\u0644\u064b\u0627 \u0645\u0646 \u0645\u0639\u0631\u0641\u0629 \u0645\u0646\u062a\u0642\u0627\u0629 \u0645\u062e\u0632\u0646\u0629 \u0639\u0644\u0649 \u062c\u0647\u0627\u0632\u0643\u060c \u062f\u0648\u0646 \u0627\u062a\u0635\u0627\u0644 \u0648\u0628\u0627\u0644\u0645\u062c\u0627\u0646. \u0648\u0625\u0646 \u0623\u0631\u062f\u062a \u0645\u062d\u0627\u062f\u062b\u0629 \u0645\u0641\u062a\u0648\u062d\u0629 \u0641\u064a\u0645\u0643\u0646\u0643 \u0644\u0635\u0642 \u0645\u0641\u062a\u0627\u062d \u0645\u0646 \u062d\u0633\u0627\u0628\u0643 \u0644\u062f\u0649 \u0634\u0631\u0643\u0629 \u0630\u0643\u0627\u0621 \u0627\u0635\u0637\u0646\u0627\u0639\u064a (Groq \u0623\u0648 OpenRouter \u0623\u0648 xAI). \u062a\u0642\u062f\u0645 \u0647\u0630\u0647 \u0627\u0644\u0634\u0631\u0643\u0627\u062a \u062e\u0637\u0637\u064b\u0627 \u0645\u062c\u0627\u0646\u064a\u0629\u061b \u0648\u0644\u0627 \u064a\u062a\u0642\u0627\u0636\u0649 \u0647\u0630\u0627 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0645\u0646\u0643 \u0634\u064a\u0626\u064b\u0627 \u0645\u0642\u0627\u0628\u0644 \u0630\u0644\u0643.","\u0622\u067e \u06a9\u0648 \u0627\u0633 \u06a9\u06cc \u0636\u0631\u0648\u0631\u062a \u0646\u06c1\u06cc\u06ba\u06d4 \u06c1\u0627\u062f\u06cc \u067e\u06c1\u0644\u06d2 \u06c1\u06cc \u0622\u067e \u06a9\u06d2 \u0622\u0644\u06d2 \u067e\u0631 \u0645\u062d\u0641\u0648\u0638 \u0645\u0646\u062a\u062e\u0628 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0633\u06d2 \u0622\u0641 \u0644\u0627\u0626\u0646 \u0627\u0648\u0631 \u0645\u0641\u062a \u062c\u0648\u0627\u0628 \u062f\u06cc\u062a\u0627 \u06c1\u06d2\u06d4 \u0627\u06af\u0631 \u0622\u067e \u06a9\u06be\u0644\u06cc \u06af\u0641\u062a\u06af\u0648 \u0686\u0627\u06c1\u062a\u06d2 \u06c1\u06cc\u06ba \u062a\u0648 \u06a9\u0633\u06cc \u0627\u06d2 \u0622\u0626\u06cc \u06a9\u0645\u067e\u0646\u06cc (Groq\u060c OpenRouter \u06cc\u0627 xAI) \u0645\u06cc\u06ba \u0627\u067e\u0646\u06d2 \u0627\u06a9\u0627\u0624\u0646\u0679 \u06a9\u06cc \u06a9\u0644\u06cc\u062f \u0686\u0633\u067e\u0627\u06ba \u06a9\u0631 \u0633\u06a9\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u06cc\u06c1 \u06a9\u0645\u067e\u0646\u06cc\u0627\u06ba \u0645\u0641\u062a \u067e\u0644\u0627\u0646 \u062f\u06cc\u062a\u06cc \u06c1\u06cc\u06ba\u061b \u06cc\u06c1 \u0627\u06cc\u067e \u0627\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0622\u067e \u0633\u06d2 \u06a9\u0686\u06be \u0646\u06c1\u06cc\u06ba \u0644\u06cc\u062a\u06cc\u06d4","\u098f\u099f\u09bf \u0986\u09aa\u09a8\u09be\u09b0 \u09a6\u09b0\u0995\u09be\u09b0 \u09a8\u09c7\u0987\u0964 \u09b9\u09be\u09a6\u09c0 \u0987\u09a4\u09bf\u09ae\u09a7\u09cd\u09af\u09c7 \u0986\u09aa\u09a8\u09be\u09b0 \u09a1\u09bf\u09ad\u09be\u0987\u09b8\u09c7 \u09b0\u09be\u0996\u09be \u09ac\u09be\u099b\u09be\u0987 \u0995\u09b0\u09be \u099c\u09cd\u099e\u09be\u09a8 \u09a5\u09c7\u0995\u09c7 \u0985\u09ab\u09b2\u09be\u0987\u09a8\u09c7, \u09ac\u09bf\u09a8\u09be\u09ae\u09c2\u09b2\u09cd\u09af\u09c7 \u0989\u09a4\u09cd\u09a4\u09b0 \u09a6\u09c7\u09af\u09bc\u0964 \u0996\u09cb\u09b2\u09be\u09ae\u09c7\u09b2\u09be \u0995\u09a5\u09cb\u09aa\u0995\u09a5\u09a8 \u099a\u09be\u0987\u09b2\u09c7 \u0986\u09aa\u09a8\u09bf \u0995\u09cb\u09a8\u09cb \u098f\u0986\u0987 \u0995\u09cb\u09ae\u09cd\u09aa\u09be\u09a8\u09bf\u09b0 (Groq, OpenRouter \u09ac\u09be xAI) \u09a8\u09bf\u099c\u09c7\u09b0 \u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f\u09c7\u09b0 \u098f\u0995\u099f\u09bf \u0995\u09c0 \u09aa\u09c7\u09b8\u09cd\u099f \u0995\u09b0\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7\u09a8\u0964 \u09b8\u09c7\u0987 \u0995\u09cb\u09ae\u09cd\u09aa\u09be\u09a8\u09bf\u0997\u09c1\u09b2\u09cb \u09ac\u09bf\u09a8\u09be\u09ae\u09c2\u09b2\u09cd\u09af\u09c7\u09b0 \u09aa\u09cd\u09b2\u09cd\u09af\u09be\u09a8 \u09a6\u09c7\u09af\u09bc; \u098f\u0987 \u0985\u09cd\u09af\u09be\u09aa \u098f\u09b0 \u099c\u09a8\u09cd\u09af \u0986\u09aa\u09a8\u09be\u09b0 \u0995\u09be\u099b \u09a5\u09c7\u0995\u09c7 \u0995\u09bf\u099b\u09c1 \u09a8\u09c7\u09af\u09bc \u09a8\u09be\u0964"],t.s)
B.aYu=s(["\u0645\u0627 \u0627\u0644\u0630\u064a \u064a\u064f\u0631\u0633\u0644 \u0645\u0639 \u0627\u0644\u0645\u0641\u062a\u0627\u062d","\u06a9\u0644\u06cc\u062f \u06a9\u06d2 \u0633\u0627\u062a\u06be \u06a9\u06cc\u0627 \u0628\u06be\u06cc\u062c\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2","\u0995\u09c0-\u098f\u09b0 \u09b8\u09be\u09a5\u09c7 \u0995\u09c0 \u09aa\u09be\u09a0\u09be\u09a8\u09cb \u09b9\u09af\u09bc"],t.s)
B.aVe=s(["\u0645\u0627 \u062a\u0643\u062a\u0628\u0647 \u0648\u0627\u0644\u0645\u062d\u0627\u062f\u062b\u0629 \u0627\u0644\u0623\u062e\u064a\u0631\u0629 \u0648\u0627\u0633\u0645\u0643 \u0625\u0646 \u0641\u0639\u0651\u0644\u062a \u0630\u0644\u0643 \u0641\u064a \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u062a\u0630\u0647\u0628 \u0625\u0644\u0649 \u0627\u0644\u0645\u0632\u0648\u0651\u062f \u0627\u0644\u0630\u064a \u062a\u062e\u062a\u0627\u0631\u0647\u060c \u0645\u0639 \u0645\u0641\u062a\u0627\u062d\u0643\u060c \u0645\u0639 \u0643\u0644 \u0633\u0624\u0627\u0644.","\u0622\u067e \u062c\u0648 \u0644\u06a9\u06be\u062a\u06d2 \u06c1\u06cc\u06ba\u060c \u062d\u0627\u0644\u06cc\u06c1 \u06af\u0641\u062a\u06af\u0648\u060c \u0627\u0648\u0631 \u0627\u06af\u0631 \u0622\u067e \u0646\u06d2 \u062a\u0631\u062a\u06cc\u0628\u0627\u062a \u0645\u06cc\u06ba \u0622\u0646 \u06a9\u06cc\u0627 \u06c1\u0648 \u062a\u0648 \u0622\u067e \u06a9\u0627 \u0646\u0627\u0645\u060c \u0622\u067e \u06a9\u06d2 \u0645\u0646\u062a\u062e\u0628 \u0641\u0631\u0627\u06c1\u0645 \u06a9\u0646\u0646\u062f\u06c1 \u06a9\u0648 \u0622\u067e \u06a9\u06cc \u06a9\u0644\u06cc\u062f \u06a9\u06d2 \u0633\u0627\u062a\u06be \u06c1\u0631 \u0633\u0648\u0627\u0644 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u062c\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4","\u0986\u09aa\u09a8\u09bf \u09af\u09be \u09b2\u09c7\u0996\u09c7\u09a8, \u09b8\u09be\u09ae\u09cd\u09aa\u09cd\u09b0\u09a4\u09bf\u0995 \u0995\u09a5\u09cb\u09aa\u0995\u09a5\u09a8, \u098f\u09ac\u0982 \u09b8\u09c7\u099f\u09bf\u0982\u09b8\u09c7 \u099a\u09be\u09b2\u09c1 \u0995\u09b0\u09b2\u09c7 \u0986\u09aa\u09a8\u09be\u09b0 \u09a8\u09be\u09ae, \u09aa\u09cd\u09b0\u09a4\u09bf\u099f\u09bf \u09aa\u09cd\u09b0\u09b6\u09cd\u09a8\u09c7\u09b0 \u09b8\u09be\u09a5\u09c7 \u0986\u09aa\u09a8\u09be\u09b0 \u0995\u09c0-\u09b8\u09b9 \u0986\u09aa\u09a8\u09be\u09b0 \u09ac\u09c7\u099b\u09c7 \u09a8\u09c7\u0993\u09af\u09bc\u09be \u09aa\u09cd\u09b0\u09a6\u09be\u09a8\u0995\u09be\u09b0\u09c0\u09b0 \u0995\u09be\u099b\u09c7 \u09af\u09be\u09af\u09bc\u0964"],t.s)
B.aYV=s(["\u0623\u064a\u0646 \u064a\u064f\u062d\u0641\u0638 \u0645\u0641\u062a\u0627\u062d\u0643","\u0622\u067e \u06a9\u06cc \u06a9\u0644\u06cc\u062f \u06a9\u06c1\u0627\u06ba \u0631\u06a9\u06be\u06cc \u062c\u0627\u062a\u06cc \u06c1\u06d2","\u0986\u09aa\u09a8\u09be\u09b0 \u0995\u09c0 \u0995\u09cb\u09a5\u09be\u09af\u09bc \u09b0\u09be\u0996\u09be \u09b9\u09af\u09bc"],t.s)
B.aNd=s(["\u0639\u0644\u0649 \u0627\u0644\u0647\u0627\u062a\u0641\u060c \u0641\u064a \u0627\u0644\u0645\u062e\u0632\u0646 \u0627\u0644\u0622\u0645\u0646 \u0644\u0644\u0647\u0627\u062a\u0641. \u0648\u0641\u064a \u0645\u062a\u0635\u0641\u062d \u0627\u0644\u0648\u064a\u0628 \u064a\u064f\u062d\u0641\u0638 \u0644\u0647\u0630\u0647 \u0627\u0644\u0632\u064a\u0627\u0631\u0629 \u0641\u0642\u0637\u060c \u0648\u062a\u0644\u0635\u0642\u0647 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0641\u064a \u0627\u0644\u0645\u0631\u0629 \u0627\u0644\u0642\u0627\u062f\u0645\u0629. \u0648\u0644\u0627 \u064a\u064f\u062d\u0641\u0638 \u0623\u0628\u062f\u064b\u0627 \u0643\u0646\u0635 \u0635\u0631\u064a\u062d. \u0627\u0633\u062a\u062e\u062f\u0645 \u0645\u0641\u062a\u0627\u062d\u064b\u0627 \u064a\u0645\u0643\u0646\u0643 \u0625\u0628\u0637\u0627\u0644\u0647.","\u0641\u0648\u0646 \u067e\u0631\u060c \u0641\u0648\u0646 \u06a9\u06d2 \u0645\u062d\u0641\u0648\u0638 \u0627\u0633\u0679\u0648\u0631 \u0645\u06cc\u06ba\u06d4 \u0648\u06cc\u0628 \u0628\u0631\u0627\u0624\u0632\u0631 \u0645\u06cc\u06ba \u06cc\u06c1 \u0635\u0631\u0641 \u0627\u0633\u06cc \u0648\u0632\u0679 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0631\u06c1\u062a\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u0627\u06af\u0644\u06cc \u0628\u0627\u0631 \u0622\u067e \u0627\u0633\u06d2 \u062f\u0648\u0628\u0627\u0631\u06c1 \u0686\u0633\u067e\u0627\u06ba \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u06cc\u06c1 \u06a9\u0628\u06be\u06cc \u0633\u0627\u062f\u06c1 \u0645\u062a\u0646 \u0645\u06cc\u06ba \u0645\u062d\u0641\u0648\u0638 \u0646\u06c1\u06cc\u06ba \u06c1\u0648\u062a\u0627\u06d4 \u0627\u06cc\u0633\u06cc \u06a9\u0644\u06cc\u062f \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0631\u06cc\u06ba \u062c\u0633\u06d2 \u0622\u067e \u0645\u0646\u0633\u0648\u062e \u06a9\u0631 \u0633\u06a9\u06cc\u06ba\u06d4","\u09ab\u09cb\u09a8\u09c7, \u09ab\u09cb\u09a8\u09c7\u09b0 \u09a8\u09bf\u09b0\u09be\u09aa\u09a6 \u09b8\u0982\u09b0\u0995\u09cd\u09b7\u09a3\u09c7\u0964 \u0993\u09af\u09bc\u09c7\u09ac \u09ac\u09cd\u09b0\u09be\u0989\u099c\u09be\u09b0\u09c7 \u098f\u099f\u09bf \u09b6\u09c1\u09a7\u09c1 \u098f\u0987 \u09b8\u09ab\u09b0\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u09a5\u09be\u0995\u09c7, \u098f\u09ac\u0982 \u09aa\u09b0\u09c7\u09b0 \u09ac\u09be\u09b0 \u0986\u09ac\u09be\u09b0 \u09aa\u09c7\u09b8\u09cd\u099f \u0995\u09b0\u09a4\u09c7 \u09b9\u09af\u09bc\u0964 \u098f\u099f\u09bf \u0995\u0996\u09a8\u0993 \u09b8\u09be\u09a7\u09be\u09b0\u09a3 \u09b2\u09c7\u0996\u09be \u09b9\u09bf\u09b8\u09c7\u09ac\u09c7 \u09b8\u0982\u09b0\u0995\u09cd\u09b7\u09bf\u09a4 \u09b9\u09af\u09bc \u09a8\u09be\u0964 \u098f\u09ae\u09a8 \u0995\u09c0 \u09ac\u09cd\u09af\u09ac\u09b9\u09be\u09b0 \u0995\u09b0\u09c1\u09a8 \u09af\u09be \u0986\u09aa\u09a8\u09bf \u09ac\u09be\u09a4\u09bf\u09b2 \u0995\u09b0\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7\u09a8\u0964"],t.s)
B.b0B=s(["\u0645\u0627 \u0644\u0627 \u064a\u063a\u0627\u062f\u0631 \u062c\u0647\u0627\u0632\u0643 \u0623\u0628\u062f\u064b\u0627","\u062c\u0648 \u0622\u067e \u06a9\u06d2 \u0622\u0644\u06d2 \u0633\u06d2 \u06a9\u0628\u06be\u06cc \u0628\u0627\u06c1\u0631 \u0646\u06c1\u06cc\u06ba \u062c\u0627\u062a\u0627","\u09af\u09be \u0986\u09aa\u09a8\u09be\u09b0 \u09a1\u09bf\u09ad\u09be\u0987\u09b8 \u099b\u09c7\u09a1\u09bc\u09c7 \u09af\u09be\u09af\u09bc \u09a8\u09be"],t.s)
B.bbG=s(["\u0627\u0644\u0631\u0633\u0627\u0626\u0644 \u0639\u0646 \u0627\u0644\u0627\u0646\u062a\u062d\u0627\u0631 \u0648\u0625\u064a\u0630\u0627\u0621 \u0627\u0644\u0646\u0641\u0633 \u0648\u0627\u0644\u0625\u0633\u0627\u0621\u0629 \u0648\u0633\u0644\u0627\u0645\u0629 \u0623\u064a \u0634\u062e\u0635\u060c \u0623\u0648 \u0639\u0646 \u0627\u0644\u0634\u0631\u0628 \u0648\u0627\u0644\u0645\u062e\u062f\u0631\u0627\u062a \u0648\u0627\u0644\u0642\u0645\u0627\u0631 \u0648\u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u0625\u0628\u0627\u062d\u064a\u0629 \u0648\u0627\u0644\u062a\u062f\u062e\u064a\u0646 \u0623\u0648 \u0627\u0644\u0627\u0646\u062a\u0643\u0627\u0633 \u064a\u064f\u062c\u0627\u0628 \u0639\u0646\u0647\u0627 \u0647\u0646\u0627 \u0639\u0644\u0649 \u062c\u0647\u0627\u0632\u0643. \u0644\u0627 \u062a\u064f\u0631\u0633\u0644 \u0623\u0628\u062f\u064b\u0627 \u0648\u0644\u0627 \u062a\u064f\u062d\u0641\u0638 \u0623\u0628\u062f\u064b\u0627 \u0648\u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u0639\u0646\u0647\u0627.","\u062e\u0648\u062f\u06a9\u0634\u06cc\u060c \u062e\u0648\u062f \u06a9\u0648 \u0646\u0642\u0635\u0627\u0646\u060c \u0632\u06cc\u0627\u062f\u062a\u06cc\u060c \u06a9\u0633\u06cc \u06a9\u06cc \u0628\u06be\u06cc \u062d\u0641\u0627\u0638\u062a\u060c \u06cc\u0627 \u0634\u0631\u0627\u0628\u060c \u0645\u0646\u0634\u06cc\u0627\u062a\u060c \u062c\u0648\u0627\u060c \u0641\u062d\u0634 \u0645\u0648\u0627\u062f\u060c \u0633\u06af\u0631\u06cc\u0679 \u0646\u0648\u0634\u06cc \u06cc\u0627 \u062f\u0648\u0628\u0627\u0631\u06c1 \u0644\u062a \u0644\u06af\u0646\u06d2 \u06a9\u06d2 \u0628\u0627\u0631\u06d2 \u0645\u06cc\u06ba \u067e\u06cc\u063a\u0627\u0645\u0627\u062a \u06a9\u0627 \u062c\u0648\u0627\u0628 \u06cc\u06c1\u06cc\u06ba \u0622\u067e \u06a9\u06d2 \u0622\u0644\u06d2 \u067e\u0631 \u062f\u06cc\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4 \u0648\u06c1 \u06a9\u0628\u06be\u06cc \u0628\u06be\u06cc\u062c\u06d2 \u0646\u06c1\u06cc\u06ba \u062c\u0627\u062a\u06d2\u060c \u06a9\u0628\u06be\u06cc \u0645\u062d\u0641\u0648\u0638 \u0646\u06c1\u06cc\u06ba \u06c1\u0648\u062a\u06d2\u060c \u0627\u0648\u0631 \u0627\u0646 \u06a9\u06cc \u0631\u067e\u0648\u0631\u0679 \u0646\u06c1\u06cc\u06ba \u06a9\u06cc \u062c\u0627 \u0633\u06a9\u062a\u06cc\u06d4","\u0986\u09a4\u09cd\u09ae\u09b9\u09a4\u09cd\u09af\u09be, \u09a8\u09bf\u099c\u09c7\u0995\u09c7 \u0986\u0998\u09be\u09a4, \u09a8\u09bf\u09b0\u09cd\u09af\u09be\u09a4\u09a8, \u0995\u09be\u09b0\u0993 \u09a8\u09bf\u09b0\u09be\u09aa\u09a4\u09cd\u09a4\u09be, \u0985\u09a5\u09ac\u09be \u09ae\u09a6, \u09ae\u09be\u09a6\u0995, \u099c\u09c1\u09af\u09bc\u09be, \u09aa\u09b0\u09cd\u09a8\u09cb\u0997\u09cd\u09b0\u09be\u09ab\u09bf, \u09a7\u09c2\u09ae\u09aa\u09be\u09a8 \u09ac\u09be \u09aa\u09c1\u09a8\u09b0\u09be\u09af\u09bc \u0986\u09b8\u0995\u09cd\u09a4\u09bf \u09a8\u09bf\u09af\u09bc\u09c7 \u09ac\u09be\u09b0\u09cd\u09a4\u09be\u09b0 \u0989\u09a4\u09cd\u09a4\u09b0 \u098f\u0996\u09be\u09a8\u09c7 \u0986\u09aa\u09a8\u09be\u09b0 \u09a1\u09bf\u09ad\u09be\u0987\u09b8\u09c7\u0987 \u09a6\u09c7\u0993\u09af\u09bc\u09be \u09b9\u09af\u09bc\u0964 \u09b8\u09c7\u0997\u09c1\u09b2\u09cb \u0995\u0996\u09a8\u0993 \u09aa\u09be\u09a0\u09be\u09a8\u09cb \u09b9\u09af\u09bc \u09a8\u09be, \u0995\u0996\u09a8\u0993 \u09b8\u0982\u09b0\u0995\u09cd\u09b7\u09bf\u09a4 \u09b9\u09af\u09bc \u09a8\u09be, \u098f\u09ac\u0982 \u09b0\u09bf\u09aa\u09cb\u09b0\u09cd\u099f \u0995\u09b0\u09be \u09af\u09be\u09af\u09bc \u09a8\u09be\u0964"],t.s)
B.b1u=s(["\u0643\u064a\u0641 \u062a\u064f\u0631\u0627\u062c\u064e\u0639 \u0627\u0644\u0625\u062c\u0627\u0628\u0627\u062a \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u0629","\u0644\u0627\u0626\u06cc\u0648 \u062c\u0648\u0627\u0628\u0627\u062a \u06a9\u06cc \u062c\u0627\u0646\u0686 \u06a9\u06cc\u0633\u06d2 \u06c1\u0648\u062a\u06cc \u06c1\u06d2","\u09b2\u09be\u0987\u09ad \u0989\u09a4\u09cd\u09a4\u09b0 \u0995\u09c0\u09ad\u09be\u09ac\u09c7 \u09af\u09be\u099a\u09be\u0987 \u0995\u09b0\u09be \u09b9\u09af\u09bc"],t.s)
B.blF=s(["\u064a\u0639\u0631\u0636 \u0647\u0627\u062f\u064a \u0627\u0644\u0646\u0635\u0648\u0635 \u0627\u0644\u0634\u0631\u0639\u064a\u0629 \u0628\u0646\u0641\u0633\u0647 \u0645\u0646 \u0645\u0643\u062a\u0628\u062a\u0647 \u0648\u064a\u062d\u0630\u0641 \u0627\u0644\u0645\u0631\u0627\u062c\u0639 \u0627\u0644\u062a\u064a \u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646\u0647\u0627. \u0647\u0627\u062f\u064a \u0644\u0644\u0628\u0627\u0644\u063a\u064a\u0646 \u0648\u0644\u064a\u0633 \u0639\u0627\u0644\u0645\u064b\u0627.","\u06c1\u0627\u062f\u06cc \u0635\u062d\u06cc\u0641\u06d2 \u06a9\u06cc \u0639\u0628\u0627\u0631\u062a\u06cc\u06ba \u0627\u067e\u0646\u06cc \u0644\u0627\u0626\u0628\u0631\u06cc\u0631\u06cc \u0633\u06d2 \u062e\u0648\u062f \u062f\u06a9\u06be\u0627\u062a\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u0648\u06c1 \u062d\u0648\u0627\u0644\u06d2 \u06c1\u0679\u0627 \u062f\u06cc\u062a\u0627 \u06c1\u06d2 \u062c\u0646 \u06a9\u06cc \u062a\u0635\u062f\u06cc\u0642 \u0648\u06c1 \u0646\u06c1\u06cc\u06ba \u06a9\u0631 \u0633\u06a9\u062a\u0627\u06d4 \u06c1\u0627\u062f\u06cc \u0628\u0627\u0644\u063a\u0648\u06ba \u06a9\u06d2 \u0644\u06cc\u06d2 \u06c1\u06d2 \u0627\u0648\u0631 \u0639\u0627\u0644\u0645 \u0646\u06c1\u06cc\u06ba\u06d4","\u09b9\u09be\u09a6\u09c0 \u09a7\u09b0\u09cd\u09ae\u0997\u09cd\u09b0\u09a8\u09cd\u09a5\u09c7\u09b0 \u0985\u0982\u09b6 \u09a8\u09bf\u099c\u09c7\u09b0 \u09b2\u09be\u0987\u09ac\u09cd\u09b0\u09c7\u09b0\u09bf \u09a5\u09c7\u0995\u09c7 \u09a8\u09bf\u099c\u09c7\u0987 \u09a6\u09c7\u0996\u09be\u09af\u09bc \u098f\u09ac\u0982 \u09af\u09c7 \u09b8\u09c2\u09a4\u09cd\u09b0 \u09af\u09be\u099a\u09be\u0987 \u0995\u09b0\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7 \u09a8\u09be \u09a4\u09be \u09b8\u09b0\u09bf\u09af\u09bc\u09c7 \u09a6\u09c7\u09af\u09bc\u0964 \u09b9\u09be\u09a6\u09c0 \u09aa\u09cd\u09b0\u09be\u09aa\u09cd\u09a4\u09ac\u09af\u09bc\u09b8\u09cd\u0995\u09a6\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u098f\u09ac\u0982 \u0986\u09b2\u09c7\u09ae \u09a8\u09af\u09bc\u0964"],t.s)
B.bai=s(["\u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0645\u0641\u062a\u0627\u062d","\u06a9\u0644\u06cc\u062f \u06c1\u0679\u0627\u0626\u06cc\u06ba","\u0995\u09c0 \u09b8\u09b0\u09be\u09a8"],t.s)
