B.bdG=s(["\u0647\u0627\u062f\u064a \xb7 \u0630\u0643\u0627\u0621 \u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0645\u0628\u0627\u0634\u0631 (\u0628\u0636\u0648\u0627\u0628\u0637 \u062d\u0645\u0627\u064a\u0629)","\u06c1\u0627\u062f\u06cc \xb7 \u0644\u0627\u0626\u06cc\u0648 \u0627\u06d2 \u0622\u0626\u06cc (\u062d\u0641\u0627\u0638\u062a\u06cc \u062d\u062f\u0648\u062f \u06a9\u06d2 \u0633\u0627\u062a\u06be)","\u09b9\u09be\u09a6\u09c0 \xb7 \u09b2\u09be\u0987\u09ad \u098f\u0986\u0987 (\u09b8\u09c1\u09b0\u0995\u09cd\u09b7\u09be-\u09b8\u09c0\u09ae\u09be\u09b8\u09b9)"],t.s)
B.bxq=s(["\u0647\u0627\u062f\u064a \xb7 \u0627\u0644\u0645\u0643\u062a\u0628\u0629 \u0627\u0644\u0645\u062f\u0645\u062c\u0629","\u06c1\u0627\u062f\u06cc \xb7 \u0628\u0644\u0679 \u0627\u0650\u0646 \u0644\u0627\u0626\u0628\u0631\u06cc\u0631\u06cc","\u09b9\u09be\u09a6\u09c0 \xb7 \u0985\u09a8\u09cd\u09a4\u09b0\u09cd\u09a8\u09bf\u09b0\u09cd\u09ae\u09bf\u09a4 \u09b2\u09be\u0987\u09ac\u09cd\u09b0\u09c7\u09b0\u09bf"],t.s)
B.Mw=s(["\u0627\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629","\u06c1\u0648\u0645 \u067e\u0631 \u0648\u0627\u067e\u0633","\u09b9\u09cb\u09ae\u09c7 \u09ab\u09bf\u09b0\u09c1\u09a8"],t.s)
B.b8W=s(["\u0623\u062d\u062a\u0627\u062c \u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0622\u0646","\u0645\u062c\u06be\u06d2 \u0627\u0628\u06be\u06cc \u0645\u062f\u062f \u0686\u0627\u06c1\u06cc\u06d2","\u098f\u0996\u09a8\u0987 \u09b8\u09be\u09b9\u09be\u09af\u09cd\u09af \u09a6\u09b0\u0995\u09be\u09b0"],t.s)
B.b9F=s(["\u062e\u064a\u0627\u0631\u0627\u062a \u0623\u062e\u0631\u0649","\u0645\u0632\u06cc\u062f \u0627\u062e\u062a\u06cc\u0627\u0631\u0627\u062a","\u0986\u09b0\u0993 \u09ac\u09bf\u0995\u09b2\u09cd\u09aa"],t.s)
