B.bvh=s(["\u0639\u0646 \u0647\u0627\u062f\u064a","\u06c1\u0627\u062f\u06cc \u06a9\u06d2 \u0628\u0627\u0631\u06d2 \u0645\u06cc\u06ba","\u09b9\u09be\u09a6\u09c0 \u09b8\u09ae\u09cd\u09aa\u09b0\u09cd\u0995\u09c7"],t.s)
B.bkO=s(["\u062d\u0633\u0627\u0628\u0643 \u0627\u0644\u062e\u0627\u0635 \u0644\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a (\u0627\u062e\u062a\u064a\u0627\u0631\u064a\u060c \u0645\u062a\u0642\u062f\u0645)","\u0622\u067e \u06a9\u0627 \u0627\u067e\u0646\u0627 \u0627\u06d2 \u0622\u0626\u06cc \u0627\u06a9\u0627\u0624\u0646\u0679 (\u0627\u062e\u062a\u06cc\u0627\u0631\u06cc\u060c \u0627\u06cc\u0688\u0648\u0627\u0646\u0633)","\u0986\u09aa\u09a8\u09be\u09b0 \u09a8\u09bf\u099c\u09c7\u09b0 \u098f\u0986\u0987 \u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f (\u0990\u099a\u09cd\u099b\u09bf\u0995, \u0989\u09a8\u09cd\u09a8\u09a4)"],t.s)
B.b6K=s(["\u0625\u062c\u0627\u0628\u0627\u062a \u0645\u0628\u0627\u0634\u0631\u0629 \xb7 \u0628\u0636\u0648\u0627\u0628\u0637 \u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u0627\u0644\u0635\u062d\u0627\u062d \u0627\u0644\u0633\u062a\u0629","\u0644\u0627\u0626\u06cc\u0648 \u062c\u0648\u0627\u0628\u0627\u062a \xb7 \u0642\u0631\u0622\u0646 \u0627\u0648\u0631 \u0635\u062d\u0627\u062d\u0650 \u0633\u062a\u06c1 \u06a9\u06cc \u062d\u0641\u0627\u0638\u062a\u06cc \u062d\u062f\u0648\u062f","\u09b2\u09be\u0987\u09ad \u0989\u09a4\u09cd\u09a4\u09b0 \xb7 \u0995\u09c1\u09b0\u0986\u09a8 \u0993 \u09b8\u09bf\u09b9\u09be\u09b9 \u09b8\u09bf\u09a4\u09cd\u09a4\u09be\u09b0 \u09b8\u09c1\u09b0\u0995\u09cd\u09b7\u09be-\u09b8\u09c0\u09ae\u09be"],t.s)
B.aNI=s(["\u0645\u062c\u0627\u0646\u064a. \u062a\u0623\u062a\u064a \u0627\u0644\u0625\u062c\u0627\u0628\u0627\u062a \u0645\u0646 \u0627\u0644\u0645\u0643\u062a\u0628\u0629 \u0627\u0644\u0645\u062f\u0645\u062c\u0629. \u062d\u0633\u0627\u0628 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062a\u0631\u0646\u062a \u0627\u062e\u062a\u064a\u0627\u0631\u064a (\u0642\u0627\u0626\u0645\u0629 \u062e\u064a\u0627\u0631\u0627\u062a \u0623\u062e\u0631\u0649\u060c \u0623\u0639\u0644\u0649 \u0627\u0644\u064a\u0645\u064a\u0646).","\u0645\u0641\u062a\u06d4 \u062c\u0648\u0627\u0628\u0627\u062a \u0628\u0644\u0679 \u0627\u0650\u0646 \u0644\u0627\u0626\u0628\u0631\u06cc\u0631\u06cc \u0633\u06d2 \u0622\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0622\u0646 \u0644\u0627\u0626\u0646 \u0627\u06d2 \u0622\u0626\u06cc \u0627\u06a9\u0627\u0624\u0646\u0679 \u0627\u062e\u062a\u06cc\u0627\u0631\u06cc \u06c1\u06d2 (\u0645\u0632\u06cc\u062f \u0627\u062e\u062a\u06cc\u0627\u0631\u0627\u062a \u06a9\u0627 \u0645\u06cc\u0646\u0648\u060c \u0627\u0648\u067e\u0631 \u062f\u0627\u0626\u06cc\u06ba)\u06d4","\u09ac\u09bf\u09a8\u09be\u09ae\u09c2\u09b2\u09cd\u09af\u09c7\u0964 \u0989\u09a4\u09cd\u09a4\u09b0 \u0986\u09b8\u09c7 \u0985\u09a8\u09cd\u09a4\u09b0\u09cd\u09a8\u09bf\u09b0\u09cd\u09ae\u09bf\u09a4 \u09b2\u09be\u0987\u09ac\u09cd\u09b0\u09c7\u09b0\u09bf \u09a5\u09c7\u0995\u09c7\u0964 \u0985\u09a8\u09b2\u09be\u0987\u09a8 \u098f\u0986\u0987 \u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f \u0990\u099a\u09cd\u099b\u09bf\u0995 (\u0986\u09b0\u0993 \u09ac\u09bf\u0995\u09b2\u09cd\u09aa \u09ae\u09c7\u09a8\u09c1, \u0989\u09aa\u09b0\u09c7 \u09a1\u09be\u09a8\u09c7)\u0964"],t.s)
B.baL=s(["\u0639\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u062f\u0631\u0627\u0633\u0629 \u0648\u0644\u064a\u0633 \u0639\u0627\u0644\u0645\u064b\u0627. \u0645\u062c\u0627\u0646\u064a \u0627\u0644\u064a\u0648\u0645. \u0627\u0644\u0645\u0632\u064a\u062f \u25be","\u0645\u0637\u0627\u0644\u0639\u06d2 \u06a9\u0627 \u0645\u0639\u0627\u0648\u0646\u060c \u0639\u0627\u0644\u0645 \u0646\u06c1\u06cc\u06ba\u06d4 \u0622\u062c \u0645\u0641\u062a\u06d4 \u0645\u0632\u06cc\u062f \u25be","\u09aa\u09a1\u09bc\u09be\u09b0 \u09b8\u09b9\u09be\u09af\u09bc\u0995, \u0986\u09b2\u09c7\u09ae \u09a8\u09a8\u0964 \u0986\u099c \u09ac\u09bf\u09a8\u09be\u09ae\u09c2\u09b2\u09cd\u09af\u09c7\u0964 \u0986\u09b0\u0993 \u25be"],t.s)
B.b1X=s(["\u0623\u0646\u0627 \u0639\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u062f\u0631\u0627\u0633\u0629 \u0648\u0644\u0633\u062a \u0639\u0627\u0644\u0645\u064b\u0627. \u0644\u0646 \u0623\u0641\u062a\u064a \u0641\u064a \u062d\u0627\u0644\u062a\u0643 \u0627\u0644\u062e\u0627\u0635\u0629\u060c \u0648\u0625\u0630\u0627 \u0644\u0645 \u0623\u0639\u0631\u0641 \u0641\u0633\u0623\u0642\u0648\u0644 \u0630\u0644\u0643.","\u0645\u06cc\u06ba \u0645\u0637\u0627\u0644\u0639\u06d2 \u06a9\u0627 \u0645\u0639\u0627\u0648\u0646 \u06c1\u0648\u06ba\u060c \u0639\u0627\u0644\u0645 \u0646\u06c1\u06cc\u06ba\u06d4 \u0645\u06cc\u06ba \u0622\u067e \u06a9\u06cc \u0630\u0627\u062a\u06cc \u0635\u0648\u0631\u062a\u0650 \u062d\u0627\u0644 \u067e\u0631 \u0641\u062a\u0648\u06cc\u0670 \u0646\u06c1\u06cc\u06ba \u062f\u0648\u06ba \u06af\u0627\u060c \u0627\u0648\u0631 \u062c\u0628 \u0645\u062c\u06be\u06d2 \u0645\u0639\u0644\u0648\u0645 \u0646\u06c1 \u06c1\u0648 \u062a\u0648 \u0635\u0627\u0641 \u06a9\u06c1\u06c1 \u062f\u0648\u06ba \u06af\u0627\u06d4","\u0986\u09ae\u09bf \u09aa\u09a1\u09bc\u09be\u09b0 \u09b8\u09b9\u09be\u09af\u09bc\u0995, \u0986\u09b2\u09c7\u09ae \u09a8\u0987\u0964 \u0986\u09aa\u09a8\u09be\u09b0 \u09a8\u09bf\u099c\u09c7\u09b0 \u09aa\u09b0\u09bf\u09b8\u09cd\u09a5\u09bf\u09a4\u09bf\u09a4\u09c7 \u0986\u09ae\u09bf \u0995\u09cb\u09a8\u09cb \u09b0\u09be\u09af\u09bc \u09a6\u09c7\u09ac \u09a8\u09be, \u0986\u09b0 \u09af\u09be \u099c\u09be\u09a8\u09bf \u09a8\u09be \u09a4\u09be \u09ac\u09b2\u09c7 \u09a6\u09c7\u09ac\u0964"],t.s)
B.aZT=s(["\u0645\u062c\u0627\u0646\u064a \u0627\u0644\u064a\u0648\u0645: \u0643\u0644 \u0634\u064a\u0621 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u0628\u0645\u0627 \u0641\u064a \u0630\u0644\u0643 \u0647\u0627\u062f\u064a. \u0644\u0627 \u0634\u064a\u0621 \u064a\u0637\u0644\u0628 \u0628\u0637\u0627\u0642\u0629. \u062e\u0637\u0629 \u0645\u062f\u0641\u0648\u0639\u0629 \u0644\u0625\u062c\u0627\u0628\u0627\u062a \u0645\u0628\u0627\u0634\u0631\u0629 \u0625\u0636\u0627\u0641\u064a\u0629 \u0645\u062e\u0637\u0637\u0629 \u0644\u0643\u0646\u0647\u0627 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d\u0629 \u0628\u0639\u062f.","\u0622\u062c \u0645\u0641\u062a: \u0627\u0633 \u0627\u06cc\u067e \u0645\u06cc\u06ba \u0633\u0628 \u06a9\u0686\u06be\u060c \u0628\u0634\u0645\u0648\u0644 \u06c1\u0627\u062f\u06cc\u06d4 \u06a9\u0648\u0626\u06cc \u0686\u06cc\u0632 \u06a9\u0627\u0631\u0688 \u0646\u06c1\u06cc\u06ba \u0645\u0627\u0646\u06af\u062a\u06cc\u06d4 \u0627\u0636\u0627\u0641\u06cc \u0644\u0627\u0626\u06cc\u0648 \u062c\u0648\u0627\u0628\u0627\u062a \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u06cc\u06a9 \u0627\u062f\u0627\u0626\u06cc\u06af\u06cc \u0648\u0627\u0644\u0627 \u067e\u0644\u0627\u0646 \u0645\u0646\u0635\u0648\u0628\u06d2 \u0645\u06cc\u06ba \u06c1\u06d2 \u0645\u06af\u0631 \u0627\u0628\u06be\u06cc \u06a9\u06be\u0644\u0627 \u0646\u06c1\u06cc\u06ba\u06d4","\u0986\u099c \u09ac\u09bf\u09a8\u09be\u09ae\u09c2\u09b2\u09cd\u09af\u09c7: \u098f\u0987 \u0985\u09cd\u09af\u09be\u09aa\u09c7\u09b0 \u09b8\u09ac\u0995\u09bf\u099b\u09c1, \u09b9\u09be\u09a6\u09c0\u09b8\u09b9\u0964 \u0995\u09bf\u099b\u09c1\u0987 \u0995\u09be\u09b0\u09cd\u09a1 \u099a\u09be\u09af\u09bc \u09a8\u09be\u0964 \u0985\u09a4\u09bf\u09b0\u09bf\u0995\u09cd\u09a4 \u09b2\u09be\u0987\u09ad \u0989\u09a4\u09cd\u09a4\u09b0\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u098f\u0995\u099f\u09bf \u09aa\u09c7\u0987\u09a1 \u09aa\u09cd\u09b2\u09cd\u09af\u09be\u09a8 \u09aa\u09b0\u09bf\u0995\u09b2\u09cd\u09aa\u09bf\u09a4, \u0995\u09bf\u09a8\u09cd\u09a4\u09c1 \u098f\u0996\u09a8\u0993 \u0996\u09cb\u09b2\u09be \u09b9\u09af\u09bc\u09a8\u09bf\u0964"],t.s)
B.boi=s(["\u0645\u0646 \u064a\u0643\u062a\u0628 \u0627\u0644\u0625\u062c\u0627\u0628\u0627\u062a\u060c \u0648\u0645\u0627 \u0644\u0627 \u0623\u0633\u062a\u0637\u064a\u0639 \u0641\u0639\u0644\u0647 \u2190","\u062c\u0648\u0627\u0628\u0627\u062a \u06a9\u0648\u0646 \u0644\u06a9\u06be\u062a\u0627 \u06c1\u06d2\u060c \u0627\u0648\u0631 \u0645\u06cc\u06ba \u06a9\u06cc\u0627 \u0646\u06c1\u06cc\u06ba \u06a9\u0631 \u0633\u06a9\u062a\u0627 \u2190","\u0989\u09a4\u09cd\u09a4\u09b0 \u0995\u09c7 \u09b2\u09c7\u0996\u09c7, \u0986\u09b0 \u0986\u09ae\u09bf \u0995\u09c0 \u09aa\u09be\u09b0\u09bf \u09a8\u09be \u2192"],t.s)
B.bnI=s(["\u0627\u0644\u0645\u0632\u064a\u062f \u0645\u0646 \u0627\u0644\u0623\u0633\u0626\u0644\u0629\u2026","\u0645\u0632\u06cc\u062f \u0633\u0648\u0627\u0644\u0627\u062a\u2026","\u0986\u09b0\u0993 \u09aa\u09cd\u09b0\u09b6\u09cd\u09a8\u2026"],t.s)
B.aYl=s(["\u0642\u064f\u0635\u0651 \u0646\u0635\u0643 \u0625\u0644\u0649 {1} \u062d\u0631\u0641\u064b\u0627. ({2}/{3})","\u0622\u067e \u06a9\u0627 \u0645\u062a\u0646 {1} \u062d\u0631\u0648\u0641 \u062a\u06a9 \u06a9\u0627\u0679 \u062f\u06cc\u0627 \u06af\u06cc\u0627\u06d4 ({2}/{3})","\u0986\u09aa\u09a8\u09be\u09b0 \u09b2\u09c7\u0996\u09be {1} \u0985\u0995\u09cd\u09b7\u09b0\u09c7 \u0995\u09be\u099f\u09be \u09b9\u09af\u09bc\u09c7\u099b\u09c7\u0964 ({2}/{3})"],t.s)
B.aW0=s(["{1}/{2} \u062d\u0631\u0641\u064b\u0627","{1}/{2} \u062d\u0631\u0648\u0641","{1}/{2} \u0985\u0995\u09cd\u09b7\u09b0"],t.s)
B.RY=s(["\u0627\u0633\u0623\u0644 \u0647\u0627\u062f\u064a","\u06c1\u0627\u062f\u06cc \u0633\u06d2 \u067e\u0648\u0686\u06be\u06cc\u06ba","\u09b9\u09be\u09a6\u09c0\u0995\u09c7 \u099c\u09bf\u099c\u09cd\u099e\u09be\u09b8\u09be \u0995\u09b0\u09c1\u09a8"],t.s)
B.btT=s(["\u0627\u0633\u0623\u0644 \u0647\u0627\u062f\u064a \u0623\u064a \u0634\u064a\u0621\u2026","\u06c1\u0627\u062f\u06cc \u0633\u06d2 \u06a9\u0686\u06be \u0628\u06be\u06cc \u067e\u0648\u0686\u06be\u06cc\u06ba\u2026","\u09b9\u09be\u09a6\u09c0\u0995\u09c7 \u09af\u09c7\u0995\u09cb\u09a8\u09cb \u0995\u09bf\u099b\u09c1 \u099c\u09bf\u099c\u09cd\u099e\u09be\u09b8\u09be \u0995\u09b0\u09c1\u09a8\u2026"],t.s)
B.bc5=s(["\u0627\u0633\u0623\u0644 \u0647\u0627\u062f\u064a \u0623\u064a \u0634\u064a\u0621..","\u06c1\u0627\u062f\u06cc \u0633\u06d2 \u06a9\u0686\u06be \u0628\u06be\u06cc \u067e\u0648\u0686\u06be\u06cc\u06ba..","\u09b9\u09be\u09a6\u09c0\u0995\u09c7 \u09af\u09c7\u0995\u09cb\u09a8\u09cb \u0995\u09bf\u099b\u09c1 \u099c\u09bf\u099c\u09cd\u099e\u09be\u09b8\u09be \u0995\u09b0\u09c1\u09a8.."],t.s)
B.aXI=s(["\u0645\u0644\u062e\u0635 \u0643\u064f\u062a\u0628 \u0644\u0647\u0630\u0627 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u0648\u0644\u064a\u0633 \u062a\u0631\u062c\u0645\u0629.","\u06cc\u06c1 \u062e\u0644\u0627\u0635\u06c1 \u0627\u0633 \u0627\u06cc\u067e \u06a9\u06d2 \u0644\u06cc\u06d2 \u0644\u06a9\u06be\u0627 \u06af\u06cc\u0627 \u06c1\u06d2\u060c \u062a\u0631\u062c\u0645\u06c1 \u0646\u06c1\u06cc\u06ba\u06d4","\u098f\u0987 \u0985\u09cd\u09af\u09be\u09aa\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u09b2\u09c7\u0996\u09be \u09b8\u09be\u09b0\u09b8\u0982\u0995\u09cd\u09b7\u09c7\u09aa, \u0985\u09a8\u09c1\u09ac\u09be\u09a6 \u09a8\u09af\u09bc\u0964"],t.s)
B.biS=s(["\u0645\u0642\u062a\u0637\u0641 \u0643\u064f\u062a\u0628 \u0644\u0647\u0630\u0627 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u0648\u0644\u064a\u0633 \u062a\u0631\u062c\u0645\u0629 \u0643\u0627\u0645\u0644\u0629.","\u06cc\u06c1 \u0627\u0642\u062a\u0628\u0627\u0633 \u0627\u0633 \u0627\u06cc\u067e \u06a9\u06d2 \u0644\u06cc\u06d2 \u0644\u06a9\u06be\u0627 \u06af\u06cc\u0627 \u06c1\u06d2\u060c \u0645\u06a9\u0645\u0644 \u062a\u0631\u062c\u0645\u06c1 \u0646\u06c1\u06cc\u06ba\u06d4","\u098f\u0987 \u0985\u09cd\u09af\u09be\u09aa\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u09b2\u09c7\u0996\u09be \u0989\u09a6\u09cd\u09a7\u09c3\u09a4\u09be\u0982\u09b6, \u09aa\u09c2\u09b0\u09cd\u09a3 \u0985\u09a8\u09c1\u09ac\u09be\u09a6 \u09a8\u09af\u09bc\u0964"],t.s)
B.bhx=s(["\u0645\u0646 \u0623\u064a\u0646 \u064a\u0623\u062a\u064a \u0647\u0630\u0627","\u06cc\u06c1 \u06a9\u06c1\u0627\u06ba \u0633\u06d2 \u0622\u06cc\u0627","\u098f\u099f\u09bf \u0995\u09cb\u09a5\u09be \u09a5\u09c7\u0995\u09c7 \u098f\u09b8\u09c7\u099b\u09c7"],t.s)
B.aZB=s(["\u0627\u0641\u062a\u062d \u0647\u0630\u0647 \u0627\u0644\u0633\u0648\u0631\u0629","\u06cc\u06c1 \u0633\u0648\u0631\u062a \u06a9\u06be\u0648\u0644\u06cc\u06ba","\u098f\u0987 \u09b8\u09c2\u09b0\u09be \u0996\u09c1\u09b2\u09c1\u09a8"],t.s)
