B.bep=s(["\u0644\u0646 \u062a\u0638\u0647\u0631 \u0627\u0644\u0645\u0648\u0627\u0642\u064a\u062a \u062d\u062a\u0649 \u062a\u062e\u062a\u0627\u0631 \u0645\u0643\u0627\u0646\u064b\u0627.","\u062c\u0628 \u062a\u06a9 \u0622\u067e \u06a9\u0648\u0626\u06cc \u062c\u06af\u06c1 \u0645\u0646\u062a\u062e\u0628 \u0646\u06c1 \u06a9\u0631\u06cc\u06ba \u06a9\u0648\u0626\u06cc \u0648\u0642\u062a \u0646\u06c1\u06cc\u06ba \u062f\u06a9\u06be\u0627\u06cc\u0627 \u062c\u0627\u062a\u0627\u06d4","\u0986\u09aa\u09a8\u09bf \u0995\u09cb\u09a8\u09cb \u09b8\u09cd\u09a5\u09be\u09a8 \u09ac\u09c7\u099b\u09c7 \u09a8\u09be \u09a8\u09c7\u0993\u09af\u09bc\u09be \u09aa\u09b0\u09cd\u09af\u09a8\u09cd\u09a4 \u0995\u09cb\u09a8\u09cb \u09b8\u09ae\u09af\u09bc \u09a6\u09c7\u0996\u09be\u09a8\u09cb \u09b9\u09af\u09bc \u09a8\u09be\u0964"],t.s)
B.beX=s(["\u062a\u0639\u062a\u0645\u062f \u0645\u0648\u0627\u0642\u064a\u062a \u0627\u0644\u0635\u0644\u0627\u0629 \u0639\u0644\u0649 \u0645\u0643\u0627\u0646\u0643\u060c \u0644\u0630\u0627 \u0644\u0627 \u062a\u0638\u0647\u0631 \u0623\u064a \u0645\u0648\u0627\u0642\u064a\u062a \u062d\u062a\u0649 \u062a\u062e\u062a\u0627\u0631. \u0627\u0636\u063a\u0637 \xab\u0645\u0648\u0642\u0639\u064a\xbb \u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0645\u0648\u0642\u0639 \u062c\u0647\u0627\u0632\u0643 \u0623\u0648 \u0645\u062a\u0635\u0641\u062d\u0643 (\u0641\u0642\u0637 \u0639\u0646\u062f \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u064a\u0647)\u060c \u0623\u0648 \xab\u0627\u0644\u0645\u062f\u064a\u0646\u0629\xbb \u0644\u0627\u062e\u062a\u064a\u0627\u0631 \u0645\u062f\u064a\u0646\u062a\u0643 \u0645\u0646 \u0627\u0644\u0642\u0627\u0626\u0645\u0629. \u062b\u0645 \u062a\u064f\u062d\u0633\u0628 \u0627\u0644\u0645\u0648\u0627\u0642\u064a\u062a \u0639\u0644\u0649 \u062c\u0647\u0627\u0632\u0643.","\u0646\u0645\u0627\u0632 \u06a9\u06d2 \u0627\u0648\u0642\u0627\u062a \u0622\u067e \u06a9\u06cc \u062c\u06af\u06c1 \u067e\u0631 \u0645\u0646\u062d\u0635\u0631 \u06c1\u06cc\u06ba\u060c \u0627\u0633 \u0644\u06cc\u06d2 \u0645\u0646\u062a\u062e\u0628 \u06a9\u06cc\u06d2 \u0628\u063a\u06cc\u0631 \u06a9\u0648\u0626\u06cc \u0648\u0642\u062a \u0646\u06c1\u06cc\u06ba \u062f\u06a9\u06be\u0627\u06cc\u0627 \u062c\u0627\u062a\u0627\u06d4 \u0627\u067e\u0646\u06d2 \u0622\u0644\u06d2 \u06cc\u0627 \u0628\u0631\u0627\u0624\u0632\u0631 \u06a9\u0627 \u0645\u0642\u0627\u0645 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \xab\u0645\u06cc\u0631\u0627 \u0645\u0642\u0627\u0645\xbb \u062f\u0628\u0627\u0626\u06cc\u06ba (\u0635\u0631\u0641 \u062a\u0628 \u062c\u0628 \u0622\u067e \u062f\u0628\u0627\u0626\u06cc\u06ba)\u060c \u06cc\u0627 \u0641\u06c1\u0631\u0633\u062a \u0633\u06d2 \u0627\u067e\u0646\u0627 \u0634\u06c1\u0631 \u0686\u0646\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \xab\u0634\u06c1\u0631\xbb \u062f\u0628\u0627\u0626\u06cc\u06ba\u06d4 \u067e\u06be\u0631 \u0627\u0648\u0642\u0627\u062a \u0622\u067e \u06a9\u06d2 \u0622\u0644\u06d2 \u067e\u0631 \u062d\u0633\u0627\u0628 \u06a9\u06cc\u06d2 \u062c\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4","\u09a8\u09be\u09ae\u09be\u099c\u09c7\u09b0 \u09b8\u09ae\u09af\u09bc \u0986\u09aa\u09a8\u09be\u09b0 \u0985\u09ac\u09b8\u09cd\u09a5\u09be\u09a8\u09c7\u09b0 \u0993\u09aa\u09b0 \u09a8\u09bf\u09b0\u09cd\u09ad\u09b0 \u0995\u09b0\u09c7, \u09a4\u09be\u0987 \u0986\u09aa\u09a8\u09bf \u09ac\u09c7\u099b\u09c7 \u09a8\u09be \u09a8\u09c7\u0993\u09af\u09bc\u09be \u09aa\u09b0\u09cd\u09af\u09a8\u09cd\u09a4 \u0995\u09cb\u09a8\u09cb \u09b8\u09ae\u09af\u09bc \u09a6\u09c7\u0996\u09be\u09a8\u09cb \u09b9\u09af\u09bc \u09a8\u09be\u0964 \u0986\u09aa\u09a8\u09be\u09b0 \u09a1\u09bf\u09ad\u09be\u0987\u09b8 \u09ac\u09be \u09ac\u09cd\u09b0\u09be\u0989\u099c\u09be\u09b0\u09c7\u09b0 \u0985\u09ac\u09b8\u09cd\u09a5\u09be\u09a8 \u09ac\u09cd\u09af\u09ac\u09b9\u09be\u09b0 \u0995\u09b0\u09a4\u09c7 \xab\u0986\u09ae\u09be\u09b0 \u0985\u09ac\u09b8\u09cd\u09a5\u09be\u09a8\xbb \u099a\u09be\u09aa\u09c1\u09a8 (\u09b6\u09c1\u09a7\u09c1 \u0986\u09aa\u09a8\u09bf \u099a\u09be\u09aa\u09b2\u09c7\u0987), \u0985\u09a5\u09ac\u09be \u09a4\u09be\u09b2\u09bf\u0995\u09be \u09a5\u09c7\u0995\u09c7 \u09b6\u09b9\u09b0 \u09ac\u09c7\u099b\u09c7 \u09a8\u09bf\u09a4\u09c7 \xab\u09b6\u09b9\u09b0\xbb \u099a\u09be\u09aa\u09c1\u09a8\u0964 \u098f\u09b0\u09aa\u09b0 \u09b8\u09ae\u09af\u09bc\u0997\u09c1\u09b2\u09cb \u0986\u09aa\u09a8\u09be\u09b0 \u09a1\u09bf\u09ad\u09be\u0987\u09b8\u09c7\u0987 \u09b9\u09bf\u09b8\u09be\u09ac \u0995\u09b0\u09be \u09b9\u09af\u09bc\u0964"],t.s)
