B.bfc=s(["\u0623\u0636\u0641 \u0641\u0648\u0627\u0635\u0644 \u0627\u0644\u0625\u0642\u0627\u0645\u0629 \u0648\u0648\u0642\u062a \u0627\u0644\u062c\u0645\u0639\u0629 \u0641\u064a \u0645\u0633\u062c\u062f\u0643 \u0644\u062a\u0638\u0647\u0631 \u0628\u062c\u0627\u0646\u0628 \u0643\u0644 \u0635\u0644\u0627\u0629.","\u0627\u067e\u0646\u06cc \u0645\u0633\u062c\u062f \u06a9\u06cc \u0627\u0642\u0627\u0645\u062a \u06a9\u06d2 \u0648\u0642\u0641\u06d2 \u0627\u0648\u0631 \u062c\u0645\u0639\u06c1 \u06a9\u0627 \u0648\u0642\u062a \u0634\u0627\u0645\u0644 \u06a9\u0631\u06cc\u06ba \u062a\u0648 \u0648\u06c1 \u06c1\u0631 \u0646\u0645\u0627\u0632 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0646\u0638\u0631 \u0622\u0626\u06cc\u06ba \u06af\u06d2\u06d4","\u0986\u09aa\u09a8\u09be\u09b0 \u09ae\u09b8\u099c\u09bf\u09a6\u09c7\u09b0 \u0987\u0995\u09be\u09ae\u09be\u09b9\u09b0 \u09ac\u09cd\u09af\u09ac\u09a7\u09be\u09a8 \u0993 \u099c\u09c1\u09ae\u09be\u09b0 \u09b8\u09ae\u09af\u09bc \u09af\u09cb\u0997 \u0995\u09b0\u09c1\u09a8, \u09a4\u09be\u09b9\u09b2\u09c7 \u09aa\u09cd\u09b0\u09a4\u09bf\u099f\u09bf \u09a8\u09be\u09ae\u09be\u099c\u09c7\u09b0 \u09aa\u09be\u09b6\u09c7 \u09a6\u09c7\u0996\u09be \u09af\u09be\u09ac\u09c7\u0964"],t.s)
B.b4y=s(["\u062a\u0638\u0647\u0631 \u0628\u062c\u0627\u0646\u0628 \u0643\u0644 \u0635\u0644\u0627\u0629 \u0623\u0639\u0644\u0627\u0647. \u0627\u0636\u063a\u0637 \u0644\u0644\u062a\u063a\u064a\u064a\u0631.","\u0627\u0648\u067e\u0631 \u06c1\u0631 \u0646\u0645\u0627\u0632 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u062f\u06a9\u06be\u0627\u0626\u06d2 \u06af\u0626\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0628\u062f\u0644\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u062f\u0628\u0627\u0626\u06cc\u06ba\u06d4","\u0989\u09aa\u09b0\u09c7 \u09aa\u09cd\u09b0\u09a4\u09bf\u099f\u09bf \u09a8\u09be\u09ae\u09be\u099c\u09c7\u09b0 \u09aa\u09be\u09b6\u09c7 \u09a6\u09c7\u0996\u09be\u09a8\u09cb \u09b9\u09af\u09bc\u09c7\u099b\u09c7\u0964 \u09ac\u09a6\u09b2\u09be\u09a4\u09c7 \u099a\u09be\u09aa\u09c1\u09a8\u0964"],t.s)
B.aW2=s(["\u062a\u064f\u062f\u062e\u0644 \u0647\u0630\u0647 \u0628\u0646\u0641\u0633\u0643 \u0645\u0646 \u0644\u0648\u062d\u0629 \u0625\u0639\u0644\u0627\u0646\u0627\u062a \u0645\u0633\u062c\u062f\u0643 \u0623\u0648 \u0645\u0648\u0642\u0639\u0647\u061b \u0644\u0627 \u064a\u062c\u0644\u0628 \u0627\u0644\u0631\u064a\u0627\u0646 \u062c\u062f\u0627\u0648\u0644 \u0627\u0644\u0645\u0633\u0627\u062c\u062f. \u062a\u064f\u062d\u062f\u064e\u0651\u062f \u0627\u0644\u0625\u0642\u0627\u0645\u0629 \u0628\u0627\u0644\u062f\u0642\u0627\u0626\u0642 \u0628\u0639\u062f \u0648\u0642\u062a \u0627\u0644\u0623\u0630\u0627\u0646 \u0627\u0644\u0645\u0639\u0631\u0648\u0636.","\u06cc\u06c1 \u0622\u067e \u062e\u0648\u062f \u0627\u067e\u0646\u06cc \u0645\u0633\u062c\u062f \u06a9\u06d2 \u0646\u0648\u0679\u0633 \u0628\u0648\u0631\u0688 \u06cc\u0627 \u0648\u06cc\u0628 \u0633\u0627\u0626\u0679 \u0633\u06d2 \u062f\u0631\u062c \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u061b \u0627\u0644\u0631\u06cc\u0627\u0646 \u0645\u0633\u062c\u062f\u0648\u06ba \u06a9\u06d2 \u0679\u0627\u0626\u0645 \u0679\u06cc\u0628\u0644 \u062e\u0648\u062f \u0646\u06c1\u06cc\u06ba \u0644\u0627\u062a\u0627\u06d4 \u0627\u0642\u0627\u0645\u062a \u062f\u06a9\u06be\u0627\u0626\u06d2 \u06af\u0626\u06d2 \u0627\u0630\u0627\u0646 \u06a9\u06d2 \u0648\u0642\u062a \u06a9\u06d2 \u0628\u0639\u062f \u06a9\u06d2 \u0645\u0646\u0679\u0648\u06ba \u0645\u06cc\u06ba \u0637\u06d2 \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u06d4","\u098f\u0997\u09c1\u09b2\u09cb \u0986\u09aa\u09a8\u09bf \u09a8\u09bf\u099c\u09c7 \u09ae\u09b8\u099c\u09bf\u09a6\u09c7\u09b0 \u09a8\u09cb\u099f\u09bf\u09b6 \u09ac\u09cb\u09b0\u09cd\u09a1 \u09ac\u09be \u0993\u09af\u09bc\u09c7\u09ac\u09b8\u09be\u0987\u099f \u09a5\u09c7\u0995\u09c7 \u09b2\u09c7\u0996\u09c7\u09a8; \u0986\u09b0-\u09b0\u09be\u0987\u09af\u09bc\u09be\u09a8 \u09ae\u09b8\u099c\u09bf\u09a6\u09c7\u09b0 \u09b8\u09ae\u09af\u09bc\u09b8\u09c2\u099a\u09bf \u0986\u09a8\u09c7 \u09a8\u09be\u0964 \u0987\u0995\u09be\u09ae\u09be\u09b9 \u09a6\u09c7\u0996\u09be\u09a8\u09cb \u0986\u099c\u09be\u09a8\u09c7\u09b0 \u09b8\u09ae\u09af\u09bc\u09c7\u09b0 \u0995\u09a4 \u09ae\u09bf\u09a8\u09bf\u099f \u09aa\u09b0\u09c7 \u09a4\u09be \u09a6\u09bf\u09af\u09bc\u09c7 \u09a0\u09bf\u0995 \u09b9\u09af\u09bc\u0964"],t.s)
