B.b9R=s(["\u0627\u0644\u0628\u0648\u0635\u0644\u0629 \u0648\u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u0634\u0645\u0633 \u0648\u0645\u0644\u0627\u062d\u0638\u0627\u062a \u0627\u0644\u062f\u0642\u0629","\u0642\u0637\u0628 \u0646\u0645\u0627\u060c \u0633\u0648\u0631\u062c \u06a9\u0627 \u0637\u0631\u06cc\u0642\u06c1 \u0627\u0648\u0631 \u062f\u0631\u0633\u062a\u06cc \u06a9\u06d2 \u0646\u0648\u0679\u0633","\u0995\u09ae\u09cd\u09aa\u09be\u09b8, \u09b8\u09c2\u09b0\u09cd\u09af \u09aa\u09a6\u09cd\u09a7\u09a4\u09bf \u0993 \u09a8\u09bf\u09b0\u09cd\u09ad\u09c1\u09b2\u09a4\u09be\u09b0 \u09a8\u09cb\u099f"],t.s)
B.but=s(["\u0637\u0631\u064a\u0642\u062a\u0627\u0646 \u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u062a\u062c\u0627\u0647 \u0627\u0644\u0643\u0639\u0628\u0629","\u06a9\u0639\u0628\u06c1 \u06a9\u06cc \u0637\u0631\u0641 \u0631\u062e \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u062f\u0648 \u0637\u0631\u06cc\u0642\u06d2","\u0995\u09be\u09ac\u09be\u09b0 \u09a6\u09bf\u0995 \u099c\u09be\u09a8\u09be\u09b0 \u09a6\u09c1\u099f\u09bf \u0989\u09aa\u09be\u09af\u09bc"],t.s)
