B.bkX=s(["\u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0627\u062a\u060c \u0648\u0645\u0627 \u064a\u062a\u0630\u0643\u0631\u0647 \u0647\u0627\u062f\u064a\u060c \u0648\u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u062e\u0627\u0635\u060c \u0648\u0627\u0644\u062e\u0631\u0648\u062c \u0627\u0644\u0633\u0631\u064a\u0639\u060c \u0648\u0627\u0644\u0643\u0644\u0645\u0629 \u0627\u0644\u0622\u0645\u0646\u0629\u060c \u0648\u0627\u0644\u0644\u063a\u0629","\u0686\u06cc\u06a9 \u0627\u0650\u0646\u060c \u06c1\u0627\u062f\u06cc \u06a9\u06cc\u0627 \u06cc\u0627\u062f \u0631\u06a9\u06be\u062a\u0627 \u06c1\u06d2\u060c \u0646\u062c\u06cc \u0645\u0648\u0688\u060c \u0641\u0648\u0631\u06cc \u0627\u062e\u0631\u0627\u062c\u060c \u0645\u062d\u0641\u0648\u0638 \u0644\u0641\u0638\u060c \u0632\u0628\u0627\u0646","\u099a\u09c7\u0995-\u0987\u09a8, \u09b9\u09be\u09a6\u09c0 \u0995\u09c0 \u09ae\u09a8\u09c7 \u09b0\u09be\u0996\u09c7, \u09aa\u09cd\u09b0\u09be\u0987\u09ad\u09c7\u099f \u09ae\u09cb\u09a1, \u09a6\u09cd\u09b0\u09c1\u09a4 \u09ac\u09c7\u09b0\u09cb\u09a8\u09cb, \u09a8\u09bf\u09b0\u09be\u09aa\u09a6 \u09b6\u09ac\u09cd\u09a6, \u09ad\u09be\u09b7\u09be"],t.s)
B.aUJ=s(["\u0643\u064a\u0641 \u064a\u0639\u0645\u0644 \u0647\u0630\u0627 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u0645\u0627 \u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639 \u0641\u0639\u0644\u0647\u060c \u0645\u0639 \u0643\u0644 \u0645\u0635\u062f\u0631 \u0646\u0633\u062a\u062e\u062f\u0645\u0647","\u06cc\u06c1 \u0627\u06cc\u067e \u06a9\u06cc\u0633\u06d2 \u06a9\u0627\u0645 \u06a9\u0631\u062a\u06cc \u06c1\u06d2 \u0627\u0648\u0631 \u06a9\u06cc\u0627 \u0646\u06c1\u06cc\u06ba \u06a9\u0631 \u0633\u06a9\u062a\u06cc\u060c \u0633\u0627\u062a\u06be \u06c1\u06cc \u06c1\u0631 \u0645\u0627\u062e\u0630 \u062c\u0648 \u06c1\u0645 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba","\u098f\u0987 \u0985\u09cd\u09af\u09be\u09aa \u0995\u09c0\u09ad\u09be\u09ac\u09c7 \u0995\u09be\u099c \u0995\u09b0\u09c7 \u0993 \u0995\u09c0 \u09aa\u09be\u09b0\u09c7 \u09a8\u09be, \u09b8\u09be\u09a5\u09c7 \u0986\u09ae\u09be\u09a6\u09c7\u09b0 \u09ac\u09cd\u09af\u09ac\u09b9\u09c3\u09a4 \u09aa\u09cd\u09b0\u09a4\u09bf\u099f\u09bf \u09b8\u09c2\u09a4\u09cd\u09b0"],t.s)
B.RD=s(["\u0645\u0627 \u0647\u0648 \u0627\u0644\u0645\u062c\u0627\u0646\u064a","\u06a9\u06cc\u0627 \u0645\u0641\u062a \u06c1\u06d2","\u0995\u09c0 \u09ac\u09bf\u09a8\u09be\u09ae\u09c2\u09b2\u09cd\u09af\u09c7"],t.s)
B.bhW=s(["\u0643\u0644 \u0634\u064a\u0621 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0645\u062c\u0627\u0646\u064a \u0627\u0644\u064a\u0648\u0645\u060c \u0628\u0645\u0627 \u0641\u064a \u0630\u0644\u0643 \u0647\u0627\u062f\u064a\u060c \u0648\u0644\u0627 \u0634\u064a\u0621 \u064a\u0637\u0644\u0628 \u0628\u0637\u0627\u0642\u0629. \u062e\u0637\u0629 \u0645\u062f\u0641\u0648\u0639\u0629 \u0644\u0625\u062c\u0627\u0628\u0627\u062a \u0645\u0628\u0627\u0634\u0631\u0629 \u0625\u0636\u0627\u0641\u064a\u0629 \u0645\u062e\u0637\u0637\u0629 \u0644\u0643\u0646\u0647\u0627 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d\u0629 \u0628\u0639\u062f. \u0631\u0628\u0637 \u062d\u0633\u0627\u0628\u0643 \u0627\u0644\u062e\u0627\u0635 \u0644\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0627\u062e\u062a\u064a\u0627\u0631\u064a \u0648\u0645\u062a\u0642\u062f\u0645: \u062a\u062c\u062f\u0647 \u0636\u0645\u0646 \u0642\u0627\u0626\u0645\u0629 \u062e\u064a\u0627\u0631\u0627\u062a \u0623\u062e\u0631\u0649 (\u0623\u0639\u0644\u0649 \u0627\u0644\u064a\u0645\u064a\u0646) \u0641\u064a \u0634\u0627\u0634\u0629 \u0647\u0627\u062f\u064a.","\u0627\u0633 \u0627\u06cc\u067e \u0645\u06cc\u06ba \u0622\u062c \u0633\u0628 \u06a9\u0686\u06be \u0645\u0641\u062a \u06c1\u06d2\u060c \u0628\u0634\u0645\u0648\u0644 \u06c1\u0627\u062f\u06cc\u060c \u0627\u0648\u0631 \u06a9\u0648\u0626\u06cc \u0686\u06cc\u0632 \u06a9\u0627\u0631\u0688 \u0646\u06c1\u06cc\u06ba \u0645\u0627\u0646\u06af\u062a\u06cc\u06d4 \u0627\u0636\u0627\u0641\u06cc \u0644\u0627\u0626\u06cc\u0648 \u062c\u0648\u0627\u0628\u0627\u062a \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u062f\u0627\u0626\u06cc\u06af\u06cc \u0648\u0627\u0644\u0627 \u067e\u0644\u0627\u0646 \u0645\u0646\u0635\u0648\u0628\u06d2 \u0645\u06cc\u06ba \u06c1\u06d2 \u0645\u06af\u0631 \u0627\u0628\u06be\u06cc \u06a9\u06be\u0644\u0627 \u0646\u06c1\u06cc\u06ba\u06d4 \u0627\u067e\u0646\u0627 \u0627\u06d2 \u0622\u0626\u06cc \u0627\u06a9\u0627\u0624\u0646\u0679 \u062c\u0648\u0691\u0646\u0627 \u0627\u062e\u062a\u06cc\u0627\u0631\u06cc \u0627\u0648\u0631 \u0627\u06cc\u0688\u0648\u0627\u0646\u0633 \u06c1\u06d2: \u06cc\u06c1 \u06c1\u0627\u062f\u06cc \u0627\u0633\u06a9\u0631\u06cc\u0646 \u067e\u0631 \u0645\u0632\u06cc\u062f \u0627\u062e\u062a\u06cc\u0627\u0631\u0627\u062a \u06a9\u06d2 \u0645\u06cc\u0646\u0648 (\u0627\u0648\u067e\u0631 \u062f\u0627\u0626\u06cc\u06ba) \u0645\u06cc\u06ba \u06c1\u06d2\u06d4","\u098f\u0987 \u0985\u09cd\u09af\u09be\u09aa\u09c7\u09b0 \u09b8\u09ac\u0995\u09bf\u099b\u09c1 \u0986\u099c \u09ac\u09bf\u09a8\u09be\u09ae\u09c2\u09b2\u09cd\u09af\u09c7, \u09b9\u09be\u09a6\u09c0\u09b8\u09b9, \u0986\u09b0 \u0995\u09bf\u099b\u09c1\u0987 \u0995\u09be\u09b0\u09cd\u09a1 \u099a\u09be\u09af\u09bc \u09a8\u09be\u0964 \u0985\u09a4\u09bf\u09b0\u09bf\u0995\u09cd\u09a4 \u09b2\u09be\u0987\u09ad \u0989\u09a4\u09cd\u09a4\u09b0\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u098f\u0995\u099f\u09bf \u09aa\u09c7\u0987\u09a1 \u09aa\u09cd\u09b2\u09cd\u09af\u09be\u09a8 \u09aa\u09b0\u09bf\u0995\u09b2\u09cd\u09aa\u09bf\u09a4, \u0995\u09bf\u09a8\u09cd\u09a4\u09c1 \u098f\u0996\u09a8\u0993 \u0996\u09cb\u09b2\u09be \u09b9\u09af\u09bc\u09a8\u09bf\u0964 \u09a8\u09bf\u099c\u09c7\u09b0 \u098f\u0986\u0987 \u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f \u09af\u09c1\u0995\u09cd\u09a4 \u0995\u09b0\u09be \u0990\u099a\u09cd\u099b\u09bf\u0995 \u0993 \u0989\u09a8\u09cd\u09a8\u09a4: \u098f\u099f\u09bf \u09b9\u09be\u09a6\u09c0 \u09aa\u09b0\u09cd\u09a6\u09be\u09b0 \u0986\u09b0\u0993 \u09ac\u09bf\u0995\u09b2\u09cd\u09aa \u09ae\u09c7\u09a8\u09c1\u09a4\u09c7 (\u0989\u09aa\u09b0\u09c7 \u09a1\u09be\u09a8\u09c7)\u0964"],t.s)
