B.bsC=s(["\u0623\u062c\u0648\u0627\u0621 \u0635\u0648\u062a\u064a\u0629 \u0647\u0627\u062f\u0626\u0629 \u0639\u0646\u062f \u0627\u0644\u0648\u0635\u0648\u0644 \u0648\u0641\u064a \u0646\u0648\u0631","\u0622\u0645\u062f \u0627\u0648\u0631 \u0646\u0648\u0631 \u067e\u0631 \u0646\u0631\u0645 \u0622\u0648\u0627\u0632\u0648\u06ba \u06a9\u0627 \u0645\u0627\u062d\u0648\u0644","\u0986\u0997\u09ae\u09a8\u09c7 \u0993 \u09a8\u09c2\u09b0\u09c7 \u09a8\u09b0\u09ae \u09b6\u09ac\u09cd\u09a6\u09c7\u09b0 \u09aa\u09b0\u09bf\u09ac\u09c7\u09b6"],t.s)
B.aUS=s(["\u0627\u0644\u0623\u0630\u0627\u0646 \u0648\u062a\u0644\u0627\u0648\u0629 \u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0628\u0635\u0648\u062a \u0639\u0627\u0644\u064d \u062a\u0639\u0645\u0644 \u062f\u0627\u0626\u0645\u064b\u0627 \u0639\u0646\u062f \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u064a\u0647\u0627 \u2014 \u0647\u0630\u0627 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0644\u0644\u0623\u062c\u0648\u0627\u0621 \u0627\u0644\u0635\u0648\u062a\u064a\u0629 \u0627\u0644\u062e\u0644\u0641\u064a\u0629 \u0641\u0642\u0637.","\u0627\u0630\u0627\u0646\u060c \u0642\u0631\u0622\u0646 \u06a9\u06cc \u062a\u0644\u0627\u0648\u062a \u0627\u0648\u0631 \u0628\u0644\u0646\u062f \u0622\u0648\u0627\u0632 \u0633\u06d2 \u067e\u0691\u06be\u0646\u0627 \u06c1\u0645\u06cc\u0634\u06c1 \u062f\u0628\u0627\u0646\u06d2 \u067e\u0631 \u0686\u0644\u062a\u06d2 \u06c1\u06cc\u06ba \u2014 \u06cc\u06c1 \u0633\u0648\u0626\u0686 \u0635\u0631\u0641 \u067e\u0633 \u0645\u0646\u0638\u0631 \u06a9\u06cc \u0622\u0648\u0627\u0632\u0648\u06ba \u06a9\u06d2 \u0644\u06cc\u06d2 \u06c1\u06d2\u06d4","\u0986\u099c\u09be\u09a8, \u0995\u09c1\u09b0\u0986\u09a8 \u09a4\u09bf\u09b2\u09be\u0993\u09af\u09bc\u09be\u09a4 \u0993 \u099c\u09cb\u09b0\u09c7 \u09aa\u09a1\u09bc\u09be \u099a\u09be\u09aa\u09b2\u09c7\u0987 \u09b8\u09ac\u09b8\u09ae\u09af\u09bc \u09ac\u09be\u099c\u09c7 \u2014 \u098f\u0987 \u09b8\u09c1\u0987\u099a \u09b6\u09c1\u09a7\u09c1 \u09aa\u09c7\u099b\u09a8\u09c7\u09b0 \u09b6\u09ac\u09cd\u09a6-\u09aa\u09b0\u09bf\u09ac\u09c7\u09b6\u09c7\u09b0 \u099c\u09a8\u09cd\u09af\u0964"],t.s)
