B.bfm=s(["\u0627\u062d\u062a\u0641\u0638 \u0628\u0633\u062c\u0644 \u062e\u0627\u0635","\u0646\u062c\u06cc \u0644\u0627\u06af \u0631\u06a9\u06be\u06cc\u06ba","\u09ac\u09cd\u09af\u0995\u09cd\u09a4\u09bf\u0997\u09a4 \u09b2\u0997 \u09b0\u09be\u0996\u09c1\u09a8"],t.s)
B.b1G=s(["\u0645\u062c\u0627\u0645\u064a\u0639 \u0648\u062a\u0642\u0648\u064a\u0645 \u0644\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u0627\u0644\u0630\u0643\u0631 \u0648\u0627\u0644\u062f\u0631\u0648\u0633\u060c \u062a\u0628\u0642\u0649 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632 \u0641\u0642\u0637. \u0627\u0644\u0635\u0644\u0648\u0627\u062a \u0648\u0627\u0644\u0635\u064a\u0627\u0645 \u062a\u0623\u062a\u064a \u0645\u0646 \u0633\u062c\u0644\u0627\u062a\u0643 \u0623\u0646\u062a \u0648\u0644\u0627 \u062a\u064f\u0634\u0627\u0631\u0643 \u0623\u0628\u062f\u064b\u0627.","\u0642\u0631\u0622\u0646 \u067e\u0691\u06be\u0646\u06d2\u060c \u0630\u06a9\u0631 \u0627\u0648\u0631 \u0627\u0633\u0628\u0627\u0642 \u06a9\u06d2 \u0645\u062c\u0645\u0648\u0639\u06d2 \u0627\u0648\u0631 \u06a9\u06cc\u0644\u0646\u0688\u0631\u060c \u0635\u0631\u0641 \u0627\u0633 \u0622\u0644\u06d2 \u067e\u0631 \u0631\u06c1\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0646\u0645\u0627\u0632 \u0627\u0648\u0631 \u0631\u0648\u0632\u06d2 \u0622\u067e \u06a9\u06d2 \u0627\u067e\u0646\u06d2 \u0644\u0627\u06af \u0633\u06d2 \u0622\u062a\u06d2 \u06c1\u06cc\u06ba \u0627\u0648\u0631 \u06a9\u0628\u06be\u06cc \u0634\u06cc\u0626\u0631 \u0646\u06c1\u06cc\u06ba \u06c1\u0648\u062a\u06d2\u06d4","\u0995\u09c1\u09b0\u0986\u09a8 \u09aa\u09be\u09a0, \u09af\u09bf\u0995\u09bf\u09b0 \u0993 \u09aa\u09be\u09a0\u09c7\u09b0 \u09ae\u09cb\u099f \u09b9\u09bf\u09b8\u09be\u09ac \u0993 \u0995\u09cd\u09af\u09be\u09b2\u09c7\u09a8\u09cd\u09a1\u09be\u09b0, \u09b6\u09c1\u09a7\u09c1 \u098f\u0987 \u09a1\u09bf\u09ad\u09be\u0987\u09b8\u09c7 \u09a5\u09be\u0995\u09c7\u0964 \u09a8\u09be\u09ae\u09be\u099c \u0993 \u09b0\u09cb\u099c\u09be \u0986\u09aa\u09a8\u09be\u09b0 \u09a8\u09bf\u099c\u09c7\u09b0 \u09b2\u0997 \u09a5\u09c7\u0995\u09c7 \u0986\u09b8\u09c7 \u098f\u09ac\u0982 \u0995\u0996\u09a8\u0993 \u09b6\u09c7\u09af\u09bc\u09be\u09b0 \u09b9\u09af\u09bc \u09a8\u09be\u0964"],t.s)
B.aT0=s(["\u064a\u062c\u0645\u0639 \u0641\u0642\u0637 \u0645\u0627 \u062a\u0633\u062c\u0651\u0644\u0647. \u0648\u0625\u064a\u0642\u0627\u0641\u0647 \u064a\u0645\u062d\u0648 \u0627\u0644\u0623\u064a\u0627\u0645 \u0627\u0644\u062a\u064a \u062d\u0641\u0638\u0647\u0627.","\u06cc\u06c1 \u0635\u0631\u0641 \u0648\u06c1\u06cc \u062c\u0645\u0639 \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u062c\u0648 \u0622\u067e \u062f\u0631\u062c \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0627\u0633\u06d2 \u0628\u0646\u062f \u06a9\u0631\u0646\u06d2 \u0633\u06d2 \u0645\u062d\u0641\u0648\u0638 \u06a9\u06cc\u06d2 \u06c1\u0648\u0626\u06d2 \u062f\u0646 \u0645\u0679 \u062c\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4","\u098f\u099f\u09bf \u09b6\u09c1\u09a7\u09c1 \u0986\u09aa\u09a8\u09bf \u09af\u09be \u09b2\u0997 \u0995\u09b0\u09c7\u09a8 \u09a4\u09be \u09af\u09cb\u0997 \u0995\u09b0\u09c7\u0964 \u098f\u099f\u09bf \u09ac\u09a8\u09cd\u09a7 \u0995\u09b0\u09b2\u09c7 \u09b8\u0982\u09b0\u0995\u09cd\u09b7\u09bf\u09a4 \u09a6\u09bf\u09a8\u0997\u09c1\u09b2\u09cb \u09ae\u09c1\u099b\u09c7 \u09af\u09be\u09af\u09bc\u0964"],t.s)
B.b6R=s(["\u0627\u0641\u062a\u062d \u0633\u062c\u0644\u064a","\u0645\u06cc\u0631\u0627 \u0644\u0627\u06af \u06a9\u06be\u0648\u0644\u06cc\u06ba","\u0986\u09ae\u09be\u09b0 \u09b2\u0997 \u0996\u09c1\u09b2\u09c1\u09a8"],t.s)
B.b7V=s(["\u0647\u0627\u062f\u064a \u064a\u062a\u0630\u0643\u0631\u0643","\u06c1\u0627\u062f\u06cc \u0622\u067e \u06a9\u0648 \u06cc\u0627\u062f \u0631\u06a9\u06be\u062a\u0627 \u06c1\u06d2","\u09b9\u09be\u09a6\u09c0 \u0986\u09aa\u09a8\u09be\u0995\u09c7 \u09ae\u09a8\u09c7 \u09b0\u09be\u0996\u09c7"],t.s)
B.bAB=s(["\u064a\u062a\u064a\u062d \u0644\u0647\u0627\u062f\u064a \u0623\u0646 \u064a\u062d\u064a\u064a\u0643 \u0628\u0627\u0633\u0645 \u062d\u0633\u0627\u0628\u0643 \u0639\u0646\u062f\u0645\u0627 \u064a\u062c\u064a\u0628 \u0639\u0628\u0631 \u062e\u062f\u0645\u0629 \u0630\u0643\u0627\u0621 \u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0623\u0639\u062f\u062f\u062a\u0647\u0627\u061b \u0648\u064a\u064f\u0631\u0633\u0644 \u0627\u0644\u0627\u0633\u0645 \u0625\u0644\u0649 \u062a\u0644\u0643 \u0627\u0644\u062e\u062f\u0645\u0629 \u0645\u0639 \u0633\u0624\u0627\u0644\u0643. \u064a\u062d\u062a\u0627\u062c \u0625\u0644\u0649 \u062d\u0633\u0627\u0628 \u0645\u0633\u062c\u0651\u0644 \u0627\u0644\u062f\u062e\u0648\u0644: \u0643\u0636\u064a\u0641 \u0644\u0627 \u064a\u0648\u062c\u062f \u0627\u0633\u0645 \u0644\u0645\u0634\u0627\u0631\u0643\u062a\u0647\u060c \u0641\u0644\u0627 \u064a\u063a\u064a\u0651\u0631 \u0634\u064a\u0626\u064b\u0627. \u0645\u062a\u0648\u0642\u0641 \u0627\u0641\u062a\u0631\u0627\u0636\u064a\u064b\u0627.","\u062c\u0628 \u06c1\u0627\u062f\u06cc \u0622\u067e \u06a9\u06cc \u0642\u0627\u0626\u0645 \u06a9\u06cc \u06c1\u0648\u0626\u06cc \u0627\u06d2 \u0622\u0626\u06cc \u0633\u0631\u0648\u0633 \u06a9\u06d2 \u0630\u0631\u06cc\u0639\u06d2 \u062c\u0648\u0627\u0628 \u062f\u06d2 \u062a\u0648 \u0627\u0633\u06d2 \u0622\u067e \u06a9\u06d2 \u0627\u06a9\u0627\u0624\u0646\u0679 \u06a9\u06d2 \u0646\u0627\u0645 \u0633\u06d2 \u0633\u0644\u0627\u0645 \u06a9\u0631\u0646\u06d2 \u062f\u06cc\u062a\u0627 \u06c1\u06d2\u061b \u0646\u0627\u0645 \u0622\u067e \u06a9\u06d2 \u0633\u0648\u0627\u0644 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0627\u0633 \u0633\u0631\u0648\u0633 \u06a9\u0648 \u0628\u06be\u06cc\u062c\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4 \u0627\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0633\u0627\u0626\u0646 \u0627\u0646 \u0627\u06a9\u0627\u0624\u0646\u0679 \u0686\u0627\u06c1\u06cc\u06d2: \u0645\u06c1\u0645\u0627\u0646 \u06a9\u06d2 \u0637\u0648\u0631 \u067e\u0631 \u0634\u06cc\u0626\u0631 \u06a9\u0631\u0646\u06d2 \u06a9\u0648 \u06a9\u0648\u0626\u06cc \u0646\u0627\u0645 \u0646\u06c1\u06cc\u06ba\u060c \u0627\u0633 \u0644\u06cc\u06d2 \u06a9\u0686\u06be \u0646\u06c1\u06cc\u06ba \u0628\u062f\u0644\u062a\u0627\u06d4 \u0628\u0637\u0648\u0631 \u0688\u06cc\u0641\u0627\u0644\u0679 \u0628\u0646\u062f\u06d4","\u0986\u09aa\u09a8\u09be\u09b0 \u09b8\u09c7\u099f \u0995\u09b0\u09be \u098f\u0986\u0987 \u09b8\u09c7\u09ac\u09be\u09b0 \u09ae\u09be\u09a7\u09cd\u09af\u09ae\u09c7 \u0989\u09a4\u09cd\u09a4\u09b0 \u09a6\u09c7\u0993\u09af\u09bc\u09be\u09b0 \u09b8\u09ae\u09af\u09bc \u09b9\u09be\u09a6\u09c0\u0995\u09c7 \u0986\u09aa\u09a8\u09be\u09b0 \u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f\u09c7\u09b0 \u09a8\u09be\u09ae\u09c7 \u09b8\u09ae\u09cd\u09ad\u09be\u09b7\u09a3 \u0995\u09b0\u09a4\u09c7 \u09a6\u09c7\u09af\u09bc; \u09a8\u09be\u09ae\u099f\u09bf \u0986\u09aa\u09a8\u09be\u09b0 \u09aa\u09cd\u09b0\u09b6\u09cd\u09a8\u09c7\u09b0 \u09b8\u09be\u09a5\u09c7 \u09b8\u09c7\u0987 \u09b8\u09c7\u09ac\u09be\u09af\u09bc \u09aa\u09be\u09a0\u09be\u09a8\u09cb \u09b9\u09af\u09bc\u0964 \u098f\u09b0 \u099c\u09a8\u09cd\u09af \u09b8\u09be\u0987\u09a8-\u0987\u09a8 \u0995\u09b0\u09be \u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f \u09b2\u09be\u0997\u09c7: \u0985\u09a4\u09bf\u09a5\u09bf \u09b9\u09bf\u09b8\u09c7\u09ac\u09c7 \u09b6\u09c7\u09af\u09bc\u09be\u09b0 \u0995\u09b0\u09be\u09b0 \u09ae\u09a4\u09cb \u09a8\u09be\u09ae \u09a8\u09c7\u0987, \u09a4\u09be\u0987 \u0995\u09bf\u099b\u09c1\u0987 \u09ac\u09a6\u09b2\u09be\u09af\u09bc \u09a8\u09be\u0964 \u09a1\u09bf\u09ab\u09b2\u09cd\u099f\u09c7 \u09ac\u09a8\u09cd\u09a7\u0964"],t.s)
B.bkZ=s(["\u0644\u0627 \u064a\u062d\u0641\u0638 \u0647\u0627\u062f\u064a \u0645\u062d\u0627\u062f\u062b\u0627\u062a\u0643. \u062a\u0628\u0642\u0649 \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0629 \u0644\u0647\u0630\u0647 \u0627\u0644\u0632\u064a\u0627\u0631\u0629 \u0641\u0642\u0637\u060c \u0648\u062a\u0632\u0648\u0644 \u0639\u0646\u062f \u0645\u063a\u0627\u062f\u0631\u062a\u0643 \u0623\u0648 \u0645\u0633\u062d\u0647\u0627 \u0623\u0648 \u0625\u063a\u0644\u0627\u0642 \u0627\u0644\u062a\u0637\u0628\u064a\u0642. \u0648\u0644\u0627 \u064a\u062d\u062a\u0641\u0638 \u0647\u0627\u062f\u064a \u0628\u0623\u064a \u0634\u064a\u0621 \u0639\u0646 \u0635\u062d\u062a\u0643 \u0623\u0648 \u0623\u062f\u0648\u064a\u062a\u0643 \u0623\u0648 \u0634\u0631\u0628\u0643 \u0623\u0648 \u0645\u062e\u062f\u0631\u0627\u062a\u0643 \u0623\u0648 \u0633\u0644\u0627\u0645\u062a\u0643\u060c \u062d\u062a\u0649 \u0644\u0648 \u0637\u0644\u0628\u062a \u0645\u0646\u0647 \u0630\u0644\u0643.","\u06c1\u0627\u062f\u06cc \u0622\u067e \u06a9\u06cc \u06af\u0641\u062a\u06af\u0648 \u0645\u062d\u0641\u0648\u0638 \u0646\u06c1\u06cc\u06ba \u06a9\u0631\u062a\u0627\u06d4 \u0648\u06c1 \u0635\u0631\u0641 \u0627\u0633 \u0648\u0632\u0679 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u0633\u06a9\u0631\u06cc\u0646 \u067e\u0631 \u0631\u06c1\u062a\u06cc \u06c1\u06d2\u060c \u0627\u0648\u0631 \u0622\u067e \u06a9\u06d2 \u062c\u0627\u0646\u06d2\u060c \u0635\u0627\u0641 \u06a9\u0631\u0646\u06d2 \u06cc\u0627 \u0627\u06cc\u067e \u0628\u0646\u062f \u06a9\u0631\u0646\u06d2 \u067e\u0631 \u062e\u062a\u0645 \u06c1\u0648 \u062c\u0627\u062a\u06cc \u06c1\u06d2\u06d4 \u06c1\u0627\u062f\u06cc \u0622\u067e \u06a9\u06cc \u0635\u062d\u062a\u060c \u062f\u0648\u0627\u0624\u06ba\u060c \u0634\u0631\u0627\u0628\u060c \u0645\u0646\u0634\u06cc\u0627\u062a \u06cc\u0627 \u062d\u0641\u0627\u0638\u062a \u06a9\u06d2 \u0628\u0627\u0631\u06d2 \u0645\u06cc\u06ba \u06a9\u0686\u06be \u0628\u06be\u06cc \u0646\u06c1\u06cc\u06ba \u0631\u06a9\u06be\u062a\u0627\u060c \u0686\u0627\u06c1\u06d2 \u0622\u067e \u06a9\u06c1\u06cc\u06ba\u06d4","\u09b9\u09be\u09a6\u09c0 \u0986\u09aa\u09a8\u09be\u09b0 \u0995\u09a5\u09cb\u09aa\u0995\u09a5\u09a8 \u09b8\u0982\u09b0\u0995\u09cd\u09b7\u09a3 \u0995\u09b0\u09c7 \u09a8\u09be\u0964 \u09b8\u09c7\u0997\u09c1\u09b2\u09cb \u09b6\u09c1\u09a7\u09c1 \u098f\u0987 \u09b8\u09ab\u09b0\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u09aa\u09b0\u09cd\u09a6\u09be\u09af\u09bc \u09a5\u09be\u0995\u09c7, \u098f\u09ac\u0982 \u0986\u09aa\u09a8\u09bf \u099a\u09b2\u09c7 \u0997\u09c7\u09b2\u09c7, \u09ae\u09c1\u099b\u09b2\u09c7 \u09ac\u09be \u0985\u09cd\u09af\u09be\u09aa \u09ac\u09a8\u09cd\u09a7 \u0995\u09b0\u09b2\u09c7 \u099a\u09b2\u09c7 \u09af\u09be\u09af\u09bc\u0964 \u09b9\u09be\u09a6\u09c0 \u0986\u09aa\u09a8\u09be\u09b0 \u09b8\u09cd\u09ac\u09be\u09b8\u09cd\u09a5\u09cd\u09af, \u0993\u09b7\u09c1\u09a7, \u09ae\u09a6, \u09ae\u09be\u09a6\u0995 \u09ac\u09be \u09a8\u09bf\u09b0\u09be\u09aa\u09a4\u09cd\u09a4\u09be \u09a8\u09bf\u09af\u09bc\u09c7 \u0995\u09bf\u099b\u09c1\u0987 \u09b0\u09be\u0996\u09c7 \u09a8\u09be, \u0986\u09aa\u09a8\u09bf \u09ac\u09b2\u09b2\u09c7\u0993 \u09a8\u09be\u0964"],t.s)
B.aVg=s(["\u0623\u0639\u062f \u0639\u0631\u0636 \u0627\u0644\u0645\u0642\u062f\u0645\u0629 \u2190","\u062a\u0639\u0627\u0631\u0641 \u062f\u0648\u0628\u0627\u0631\u06c1 \u062f\u06cc\u06a9\u06be\u06cc\u06ba \u2190","\u09ad\u09c2\u09ae\u09bf\u0995\u09be \u0986\u09ac\u09be\u09b0 \u09a6\u09c7\u0996\u09c1\u09a8 \u2192"],t.s)
B.bdR=s(["\u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a \u0648\u0627\u0644\u062d\u0633\u0627\u0628","\u0642\u0627\u0646\u0648\u0646\u06cc \u0627\u0648\u0631 \u0627\u06a9\u0627\u0624\u0646\u0679","\u0986\u0987\u09a8\u09bf \u0993 \u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f"],t.s)
B.aU5=s(["\u0627\u0641\u062a\u062d \u0634\u0631\u0648\u0637 \u0627\u0644\u062e\u062f\u0645\u0629","\u0633\u0631\u0648\u0633 \u06a9\u06cc \u0634\u0631\u0627\u0626\u0637 \u06a9\u06be\u0648\u0644\u06cc\u06ba","\u09aa\u09b0\u09bf\u09b7\u09c7\u09ac\u09be\u09b0 \u09b6\u09b0\u09cd\u09a4 \u0996\u09c1\u09b2\u09c1\u09a8"],t.s)
B.bsS=s(["\u0634\u0631\u0648\u0637 \u0627\u0644\u062e\u062f\u0645\u0629 (\u0645\u0633\u0648\u062f\u0629\u060c \u0644\u0645 \u064a\u0631\u0627\u062c\u0639\u0647\u0627 \u0645\u062d\u0627\u0645\u064d \u0628\u0639\u062f) \u2190","\u0633\u0631\u0648\u0633 \u06a9\u06cc \u0634\u0631\u0627\u0626\u0637 (\u0645\u0633\u0648\u062f\u06c1\u060c \u0627\u0628\u06be\u06cc \u06a9\u0633\u06cc \u0648\u06a9\u06cc\u0644 \u0646\u06d2 \u0646\u06c1\u06cc\u06ba \u062f\u06cc\u06a9\u06be\u0627) \u2190","\u09aa\u09b0\u09bf\u09b7\u09c7\u09ac\u09be\u09b0 \u09b6\u09b0\u09cd\u09a4 (\u0996\u09b8\u09a1\u09bc\u09be, \u098f\u0996\u09a8\u0993 \u0995\u09cb\u09a8\u09cb \u0986\u0987\u09a8\u099c\u09c0\u09ac\u09c0 \u09a6\u09c7\u0996\u09c7\u09a8\u09a8\u09bf) \u2192"],t.s)
B.bpc=s(["\u0627\u0641\u062a\u062d \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629","\u067e\u0631\u0627\u0626\u06cc\u0648\u06cc\u0633\u06cc \u067e\u0627\u0644\u06cc\u0633\u06cc \u06a9\u06be\u0648\u0644\u06cc\u06ba","\u0997\u09cb\u09aa\u09a8\u09c0\u09af\u09bc\u09a4\u09be \u09a8\u09c0\u09a4\u09bf \u0996\u09c1\u09b2\u09c1\u09a8"],t.s)
B.bmW=s(["\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629 \u2190","\u067e\u0631\u0627\u0626\u06cc\u0648\u06cc\u0633\u06cc \u067e\u0627\u0644\u06cc\u0633\u06cc \u2190","\u0997\u09cb\u09aa\u09a8\u09c0\u09af\u09bc\u09a4\u09be \u09a8\u09c0\u09a4\u09bf \u2192"],t.s)
B.aO8=s(["\u0627\u062d\u0630\u0641 \u062d\u0633\u0627\u0628\u064a \u0648\u0628\u064a\u0627\u0646\u0627\u062a\u064a","\u0645\u06cc\u0631\u0627 \u0627\u06a9\u0627\u0624\u0646\u0679 \u0627\u0648\u0631 \u0688\u06cc\u0679\u0627 \u062d\u0630\u0641 \u06a9\u0631\u06cc\u06ba","\u0986\u09ae\u09be\u09b0 \u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f \u0993 \u09a1\u09c7\u099f\u09be \u09ae\u09c1\u099b\u09c1\u09a8"],t.s)
B.b5u=s(["\u0627\u062d\u0630\u0641 \u062d\u0633\u0627\u0628\u064a \u2190","\u0645\u06cc\u0631\u0627 \u0627\u06a9\u0627\u0624\u0646\u0679 \u062d\u0630\u0641 \u06a9\u0631\u06cc\u06ba \u2190","\u0986\u09ae\u09be\u09b0 \u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f \u09ae\u09c1\u099b\u09c1\u09a8 \u2192"],t.s)
B.b5F=s(["\u0644\u0633\u0627\u0646\u0643\u060c \u0627\u062e\u062a\u064a\u0627\u0631\u0643","\u0622\u067e \u06a9\u06cc \u0632\u0628\u0627\u0646\u060c \u0622\u067e \u06a9\u06cc \u0645\u0631\u0636\u06cc","\u0986\u09aa\u09a8\u09be\u09b0 \u09ad\u09be\u09b7\u09be, \u0986\u09aa\u09a8\u09be\u09b0 \u09aa\u099b\u09a8\u09cd\u09a6"],t.s)
B.b2I=s(["\u0627\u0644\u0645\u062a\u0631\u062c\u0645 \u0627\u0644\u064a\u0648\u0645\u060c \u0628\u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u0646\u063a\u0627\u0644\u064a\u0629 \u0648\u0627\u0644\u0623\u0631\u062f\u064a\u0629: \u0627\u0644\u0642\u0648\u0627\u0626\u0645 \u0648\u0623\u0633\u0645\u0627\u0621 \u0627\u0644\u062a\u0628\u0648\u064a\u0628\u0627\u062a\u060c \u0648\u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629\u060c \u0648\u0627\u0644\u0623\u0633\u0626\u0644\u0629 \u0627\u0644\u0623\u0648\u0644\u0649\u060c \u0648\u0645\u0648\u0627\u0642\u064a\u062a \u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0648\u0627\u0644\u0642\u0628\u0644\u0629\u060c \u0648\u0634\u0627\u0634\u0629 \u0647\u0627\u062f\u064a \u0648\u0623\u0632\u0631\u0627\u0631\u0647\u0627\u060c \u0648\u0639\u0646\u0627\u0648\u064a\u0646 \u0634\u0627\u0634\u0629 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0648\u0627\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u0648\u0627\u0644\u0639\u0627\u0626\u0644\u0629\u060c \u0648\u0623\u0646\u062a\u060c \u0648\u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a\u060c \u0648\u0627\u0644\u062f\u0639\u0645 \u0648\u0627\u0644\u0639\u0627\u0641\u064a\u0629\u060c \u0648\u0645\u0635\u0627\u062f\u0631\u0646\u0627\u060c \u0648\u0646\u0627\u0641\u0630\u0629 \xab\u0623\u062d\u062a\u0627\u062c \u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0622\u0646\xbb\u060c \u0648\u0623\u0647\u0645 \u0631\u062f\u0648\u062f \u0627\u0644\u0623\u0632\u0645\u0627\u062a \u0648\u0627\u0644\u062f\u0639\u0645. \u0643\u0644 \u0630\u0644\u0643 \u0645\u0633\u0648\u062f\u0629 \u0622\u0644\u064a\u0629 \u0644\u0645 \u064a\u0631\u0627\u062c\u0639\u0647\u0627 \u0623\u064a \u0645\u062a\u062d\u062f\u062b \u0623\u0635\u0644\u064a \u0628\u0639\u062f\u060c \u0648\u0627\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u062d\u0645\u0644 \u0645\u062d\u062a\u0648\u0649 \u062f\u0639\u0645 \u0623\u0648 \u0633\u0644\u0627\u0645\u0629 \u0623\u0648 \u0645\u062d\u062a\u0648\u0649 \u062f\u064a\u0646\u064a\u064b\u0627 \u062a\u0630\u0643\u0631 \u0630\u0644\u0643 \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0629. \u0627\u0644\u062f\u0631\u0648\u0633 \u0648\u0627\u0644\u0642\u0635\u0635 \u0648\u0627\u0644\u062d\u062f\u064a\u062b \u0648\u0625\u062c\u0627\u0628\u0627\u062a \u0647\u0627\u062f\u064a \u0648\u0627\u0644\u0646\u0635\u0648\u0635 \u0627\u0644\u062f\u064a\u0646\u064a\u0629 \u0627\u0644\u0637\u0648\u064a\u0644\u0629 \u0645\u0627 \u0632\u0627\u0644\u062a \u0628\u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629\u060c \u0645\u0639 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0627\u0644\u0623\u0635\u0644\u064a\u0629 \u0644\u0644\u0646\u0635\u0648\u0635 \u0627\u0644\u0634\u0631\u0639\u064a\u0629. \u0648\u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0623\u0631\u062f\u064a\u0629 \u062a\u0642\u0644\u0628\u0627\u0646 \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0645\u0646 \u0627\u0644\u064a\u0645\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u064a\u0633\u0627\u0631. \u0627\u0644\u0625\u0646\u062f\u0648\u0646\u064a\u0633\u064a\u0629 \u0641\u064a\u0647\u0627 \u0639\u0646\u0627\u0648\u064a\u0646 \u0627\u0644\u0644\u063a\u0629 \u0648\u0627\u0644\u0635\u0648\u062a \u0641\u0642\u0637\u061b \u0648\u0627\u0644\u0641\u0631\u0646\u0633\u064a\u0629 \u0648\u0627\u0644\u062a\u0631\u0643\u064a\u0629 \u0648\u0627\u0644\u0645\u0644\u0627\u064a\u0648 \u063a\u064a\u0631 \u0645\u062a\u0631\u062c\u0645\u0629 \u0628\u0639\u062f \u0648\u064a\u0628\u0642\u0649 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0628\u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629.","\u0622\u062c \u0639\u0631\u0628\u06cc\u060c \u0628\u0646\u06af\u0644\u06c1 \u0627\u0648\u0631 \u0627\u0631\u062f\u0648 \u0645\u06cc\u06ba \u062a\u0631\u062c\u0645\u06c1 \u0634\u062f\u06c1: \u0645\u06cc\u0646\u0648 \u0627\u0648\u0631 \u0679\u06cc\u0628 \u06a9\u06d2 \u0646\u0627\u0645\u060c \u06c1\u0648\u0645\u060c \u067e\u06c1\u0644\u06d2 \u0633\u0648\u0627\u0644\u0627\u062a\u060c \u0646\u0645\u0627\u0632 \u06a9\u06d2 \u0627\u0648\u0642\u0627\u062a\u060c \u0642\u0628\u0644\u06c1\u060c \u06c1\u0627\u062f\u06cc \u0627\u0633\u06a9\u0631\u06cc\u0646 \u0627\u0648\u0631 \u0627\u0633 \u06a9\u06d2 \u0628\u0679\u0646\u060c \u0642\u0631\u0622\u0646 \u0627\u0633\u06a9\u0631\u06cc\u0646 \u06a9\u06d2 \u0639\u0646\u0648\u0627\u0646\u0627\u062a\u060c \u0627\u06cc\u0645\u0627\u0646\u060c \u062e\u0627\u0646\u062f\u0627\u0646\u060c \u0622\u067e\u060c \u062a\u0631\u062a\u06cc\u0628\u0627\u062a\u060c \u0633\u067e\u0648\u0631\u0679 \u0627\u0648\u0631 \u062e\u06cc\u0631\u06cc\u062a\u060c \u06c1\u0645\u0627\u0631\u06d2 \u0630\u0631\u0627\u0626\u0639\u060c \xab\u0645\u062c\u06be\u06d2 \u0627\u0628\u06be\u06cc \u0645\u062f\u062f \u0686\u0627\u06c1\u06cc\u06d2\xbb \u0634\u06cc\u0679\u060c \u0627\u0648\u0631 \u0627\u06c1\u0645 \u0628\u062d\u0631\u0627\u0646 \u0648 \u0633\u067e\u0648\u0631\u0679 \u062c\u0648\u0627\u0628\u0627\u062a\u06d4 \u0627\u0646 \u0645\u06cc\u06ba \u0633\u06d2 \u06c1\u0631 \u0627\u06cc\u06a9 \u0645\u0634\u06cc\u0646 \u0633\u06d2 \u062a\u06cc\u0627\u0631 \u06a9\u0631\u062f\u06c1 \u0645\u0633\u0648\u062f\u06c1 \u06c1\u06d2 \u062c\u0633\u06d2 \u0627\u0628\u06be\u06cc \u06a9\u0633\u06cc \u0645\u0627\u062f\u0631\u06cc \u0632\u0628\u0627\u0646 \u0628\u0648\u0644\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0646\u06d2 \u0646\u06c1\u06cc\u06ba \u062f\u06cc\u06a9\u06be\u0627\u060c \u0627\u0648\u0631 \u062c\u0646 \u0627\u0633\u06a9\u0631\u06cc\u0646\u0648\u06ba \u0645\u06cc\u06ba \u0633\u067e\u0648\u0631\u0679\u060c \u062d\u0641\u0627\u0638\u062a \u06cc\u0627 \u0645\u0630\u06c1\u0628\u06cc \u0645\u0648\u0627\u062f \u06c1\u06d2 \u0648\u06c1 \u0627\u0633\u06a9\u0631\u06cc\u0646 \u067e\u0631 \u06cc\u06c1 \u0628\u062a\u0627\u062a\u06cc \u06c1\u06cc\u06ba\u06d4 \u0627\u0633\u0628\u0627\u0642\u060c \u06a9\u06c1\u0627\u0646\u06cc\u0627\u06ba\u060c \u062d\u062f\u06cc\u062b\u060c \u06c1\u0627\u062f\u06cc \u06a9\u06d2 \u062c\u0648\u0627\u0628\u0627\u062a \u0627\u0648\u0631 \u0637\u0648\u06cc\u0644 \u0645\u0630\u06c1\u0628\u06cc \u0645\u062a\u0648\u0646 \u0627\u0628 \u0628\u06be\u06cc \u0627\u0646\u06af\u0631\u06cc\u0632\u06cc \u0645\u06cc\u06ba \u06c1\u06cc\u06ba\u060c \u0635\u062d\u06cc\u0641\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u0635\u0644 \u0639\u0631\u0628\u06cc \u06a9\u06d2 \u0633\u0627\u062a\u06be\u06d4 \u0639\u0631\u0628\u06cc \u0627\u0648\u0631 \u0627\u0631\u062f\u0648 \u0644\u06d2 \u0622\u0624\u0679 \u06a9\u0648 \u062f\u0627\u0626\u06cc\u06ba \u0633\u06d2 \u0628\u0627\u0626\u06cc\u06ba \u0628\u06be\u06cc \u06a9\u0631 \u062f\u06cc\u062a\u06cc \u06c1\u06cc\u06ba\u06d4 \u0627\u0646\u0688\u0648\u0646\u06cc\u0634\u06cc\u0627\u0626\u06cc \u0645\u06cc\u06ba \u0635\u0631\u0641 \u0632\u0628\u0627\u0646 \u0627\u0648\u0631 \u0622\u0648\u0627\u0632 \u06a9\u06d2 \u0639\u0646\u0648\u0627\u0646\u0627\u062a \u06c1\u06cc\u06ba\u061b \u0641\u0631\u0627\u0646\u0633\u06cc\u0633\u06cc\u060c \u062a\u0631\u06a9\u06cc \u0627\u0648\u0631 \u0645\u0644\u06d2 \u06a9\u0627 \u062a\u0631\u062c\u0645\u06c1 \u0627\u0628\u06be\u06cc \u0646\u06c1\u06cc\u06ba \u06c1\u0648\u0627 \u0627\u0648\u0631 \u0627\u06cc\u067e \u0627\u0646\u06af\u0631\u06cc\u0632\u06cc \u0645\u06cc\u06ba \u0631\u06c1\u062a\u06cc \u06c1\u06d2\u06d4","\u0986\u099c \u0986\u09b0\u09ac\u09bf, \u09ac\u09be\u0982\u09b2\u09be \u0993 \u0989\u09b0\u09cd\u09a6\u09c1\u09a4\u09c7 \u0985\u09a8\u09c2\u09a6\u09bf\u09a4: \u09ae\u09c7\u09a8\u09c1 \u0993 \u099f\u09cd\u09af\u09be\u09ac\u09c7\u09b0 \u09a8\u09be\u09ae, \u09b9\u09cb\u09ae, \u09aa\u09cd\u09b0\u09a5\u09ae \u09aa\u09cd\u09b0\u09b6\u09cd\u09a8\u0997\u09c1\u09b2\u09cb, \u09a8\u09be\u09ae\u09be\u099c\u09c7\u09b0 \u09b8\u09ae\u09af\u09bc, \u0995\u09bf\u09ac\u09b2\u09be, \u09b9\u09be\u09a6\u09c0 \u09aa\u09b0\u09cd\u09a6\u09be \u0993 \u09a4\u09be\u09b0 \u09ac\u09cb\u09a4\u09be\u09ae, \u0995\u09c1\u09b0\u0986\u09a8 \u09aa\u09b0\u09cd\u09a6\u09be\u09b0 \u09b2\u09c7\u09ac\u09c7\u09b2, \u0988\u09ae\u09be\u09a8, \u09aa\u09b0\u09bf\u09ac\u09be\u09b0, \u0986\u09aa\u09a8\u09bf, \u09b8\u09c7\u099f\u09bf\u0982\u09b8, \u09b8\u09b9\u09be\u09af\u09bc\u09a4\u09be \u0993 \u09b8\u09c1\u09b8\u09cd\u09a5\u09a4\u09be, \u0986\u09ae\u09be\u09a6\u09c7\u09b0 \u09b8\u09c2\u09a4\u09cd\u09b0, \xab\u098f\u0996\u09a8\u0987 \u09b8\u09be\u09b9\u09be\u09af\u09cd\u09af \u09a6\u09b0\u0995\u09be\u09b0\xbb \u09b6\u09bf\u099f, \u098f\u09ac\u0982 \u09aa\u09cd\u09b0\u09a7\u09be\u09a8 \u09b8\u0982\u0995\u099f \u0993 \u09b8\u09b9\u09be\u09af\u09bc\u09a4\u09be\u09b0 \u0989\u09a4\u09cd\u09a4\u09b0\u0964 \u098f\u09b0 \u09aa\u09cd\u09b0\u09a4\u09bf\u099f\u09bf \u098f\u0995\u099f\u09bf \u09af\u09be\u09a8\u09cd\u09a4\u09cd\u09b0\u09bf\u0995 \u0996\u09b8\u09a1\u09bc\u09be \u09af\u09be \u098f\u0996\u09a8\u0993 \u0995\u09cb\u09a8\u09cb \u09ae\u09be\u09a4\u09c3\u09ad\u09be\u09b7\u09c0 \u09af\u09be\u099a\u09be\u0987 \u0995\u09b0\u09c7\u09a8\u09a8\u09bf, \u098f\u09ac\u0982 \u09af\u09c7\u09b8\u09ac \u09aa\u09b0\u09cd\u09a6\u09be\u09af\u09bc \u09b8\u09b9\u09be\u09af\u09bc\u09a4\u09be, \u09a8\u09bf\u09b0\u09be\u09aa\u09a4\u09cd\u09a4\u09be \u09ac\u09be \u09a7\u09b0\u09cd\u09ae\u09c0\u09af\u09bc \u09ac\u09bf\u09b7\u09af\u09bc\u09ac\u09b8\u09cd\u09a4\u09c1 \u0986\u099b\u09c7 \u09b8\u09c7\u0997\u09c1\u09b2\u09cb \u09aa\u09b0\u09cd\u09a6\u09be\u09a4\u09c7\u0987 \u09a4\u09be \u099c\u09be\u09a8\u09be\u09af\u09bc\u0964 \u09aa\u09be\u09a0, \u0997\u09b2\u09cd\u09aa, \u09b9\u09be\u09a6\u09bf\u09b8, \u09b9\u09be\u09a6\u09c0\u09b0 \u0989\u09a4\u09cd\u09a4\u09b0 \u0993 \u09a6\u09c0\u09b0\u09cd\u0998 \u09a7\u09b0\u09cd\u09ae\u09c0\u09af\u09bc \u09b2\u09c7\u0996\u09be \u098f\u0996\u09a8\u0993 \u0987\u0982\u09b0\u09c7\u099c\u09bf\u09a4\u09c7, \u09a7\u09b0\u09cd\u09ae\u0997\u09cd\u09b0\u09a8\u09cd\u09a5\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u09ae\u09c2\u09b2 \u0986\u09b0\u09ac\u09bf\u09b8\u09b9\u0964 \u0986\u09b0\u09ac\u09bf \u0993 \u0989\u09b0\u09cd\u09a6\u09c1 \u09b2\u09c7\u0986\u0989\u099f\u0995\u09c7 \u09a1\u09be\u09a8 \u09a5\u09c7\u0995\u09c7 \u09ac\u09be\u09ae\u09c7\u0993 \u0998\u09cb\u09b0\u09be\u09af\u09bc\u0964 \u0987\u09a8\u09cd\u09a6\u09cb\u09a8\u09c7\u09b6\u09c0\u09af\u09bc \u09ad\u09be\u09b7\u09be\u09af\u09bc \u09b6\u09c1\u09a7\u09c1 \u09ad\u09be\u09b7\u09be \u0993 \u0995\u09a3\u09cd\u09a0\u09c7\u09b0 \u09b2\u09c7\u09ac\u09c7\u09b2 \u0986\u099b\u09c7; \u09ab\u09b0\u09be\u09b8\u09bf, \u09a4\u09c1\u09b0\u09cd\u0995\u09bf \u0993 \u09ae\u09be\u09b2\u09af\u09bc \u098f\u0996\u09a8\u0993 \u0985\u09a8\u09c2\u09a6\u09bf\u09a4 \u09b9\u09af\u09bc\u09a8\u09bf \u098f\u09ac\u0982 \u0985\u09cd\u09af\u09be\u09aa \u0987\u0982\u09b0\u09c7\u099c\u09bf\u09a4\u09c7 \u09a5\u09be\u0995\u09c7\u0964"],t.s)
B.aYn=s(["\u0627\u0644\u0623\u0635\u0648\u0627\u062a \u0627\u0644\u0637\u0628\u064a\u0639\u064a\u0629 \u0627\u0644\u0634\u0628\u064a\u0647\u0629 \u0628\u0627\u0644\u0628\u0634\u0631 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d\u0629 \u0628\u0639\u062f. \u0648\u0625\u0644\u0649 \u0623\u0646 \u062a\u062a\u0648\u0641\u0631\u060c \u064a\u0642\u0631\u0623 \u0627\u0644\u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0644\u0645\u0627\u062a \u0628\u0635\u0648\u062a\u0647 \u0627\u0644\u062e\u0627\u0635.","\u0642\u062f\u0631\u062a\u06cc\u060c \u0627\u0646\u0633\u0627\u0646\u06cc \u0622\u0648\u0627\u0632 \u062c\u06cc\u0633\u06cc \u0622\u0648\u0627\u0632\u06cc\u06ba \u0627\u0628\u06be\u06cc \u062f\u0633\u062a\u06cc\u0627\u0628 \u0646\u06c1\u06cc\u06ba\u06d4 \u062c\u0628 \u062a\u06a9 \u0648\u06c1 \u0646\u06c1\u06cc\u06ba \u0622\u062a\u06cc\u06ba\u060c \u0622\u0644\u06c1 \u0627\u0644\u0641\u0627\u0638 \u0627\u067e\u0646\u06cc \u0622\u0648\u0627\u0632 \u0645\u06cc\u06ba \u067e\u0691\u06be\u062a\u0627 \u06c1\u06d2\u06d4","\u09b8\u09cd\u09ac\u09be\u09ad\u09be\u09ac\u09bf\u0995, \u09ae\u09be\u09a8\u09c1\u09b7\u09c7\u09b0 \u09ae\u09a4\u09cb \u0995\u09a3\u09cd\u09a0 \u098f\u0996\u09a8\u0993 \u09a8\u09c7\u0987\u0964 \u09af\u09a4\u09a6\u09bf\u09a8 \u09a8\u09be \u0986\u09b8\u09c7, \u09a1\u09bf\u09ad\u09be\u0987\u09b8 \u09a8\u09bf\u099c\u09c7\u09b0 \u0995\u09a3\u09cd\u09a0\u09c7\u0987 \u09b6\u09ac\u09cd\u09a6\u0997\u09c1\u09b2\u09cb \u09aa\u09a1\u09bc\u09c7\u0964"],t.s)
