B.bsc=s(["\u062a\u0634\u063a\u064a\u0644 \u0648\u0636\u0639 \u0643\u0628\u0627\u0631 \u0627\u0644\u0633\u0646\u061f","\u0628\u0632\u0631\u06af \u0645\u0648\u0688 \u0622\u0646 \u06a9\u0631\u06cc\u06ba\u061f","\u09aa\u09cd\u09b0\u09ac\u09c0\u09a3 \u09ae\u09cb\u09a1 \u099a\u09be\u09b2\u09c1 \u0995\u09b0\u09ac\u09c7\u09a8?"],t.s)
B.aMX=s(["\u0633\u064a\u0641\u062a\u062d \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0639\u0644\u0649 \u0635\u0641\u062d\u0629 \u0631\u0626\u064a\u0633\u064a\u0629 \u0628\u0633\u064a\u0637\u0629 \u0628\u062e\u0637 \u0643\u0628\u064a\u0631 \u0648\u0628\u0636\u0639\u0629 \u0623\u0628\u0648\u0627\u0628 \u0628\u0633\u064a\u0637\u0629 \u0641\u064a \u0643\u0644 \u0645\u0631\u0629\u060c \u062d\u062a\u0649 \u062a\u0648\u0642\u0641 \u0648\u0636\u0639 \u0643\u0628\u0627\u0631 \u0627\u0644\u0633\u0646 (\u0645\u0646 \u062a\u0644\u0643 \u0627\u0644\u0635\u0641\u062d\u0629 \u0623\u0648 \u0645\u0646 \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a).","\u0627\u06cc\u067e \u06c1\u0631 \u0628\u0627\u0631 \u0628\u0691\u06d2 \u0627\u0644\u0641\u0627\u0638 \u0627\u0648\u0631 \u0686\u0646\u062f \u0633\u0627\u062f\u06c1 \u062f\u0631\u0648\u0627\u0632\u0648\u06ba \u0648\u0627\u0644\u06d2 \u0633\u0627\u062f\u06c1 \u06c1\u0648\u0645 \u067e\u0631 \u06a9\u06be\u0644\u06d2 \u06af\u06cc\u060c \u062c\u0628 \u062a\u06a9 \u0622\u067e \u0628\u0632\u0631\u06af \u0645\u0648\u0688 \u0628\u0646\u062f \u0646\u06c1 \u06a9\u0631\u06cc\u06ba (\u0627\u0633\u06cc \u06c1\u0648\u0645 \u067e\u0631 \u06cc\u0627 \u062a\u0631\u062a\u06cc\u0628\u0627\u062a \u0645\u06cc\u06ba)\u06d4","\u0985\u09cd\u09af\u09be\u09aa \u09aa\u09cd\u09b0\u09a4\u09bf\u09ac\u09be\u09b0 \u09ac\u09a1\u09bc \u0985\u0995\u09cd\u09b7\u09b0 \u0993 \u0995\u09af\u09bc\u09c7\u0995\u099f\u09bf \u09b8\u09b9\u099c \u09a6\u09b0\u099c\u09be\u09b8\u09b9 \u098f\u0995\u099f\u09bf \u09b8\u09b9\u099c \u09b9\u09cb\u09ae\u09c7 \u0996\u09c1\u09b2\u09ac\u09c7, \u09af\u09a4\u0995\u09cd\u09b7\u09a3 \u09a8\u09be \u0986\u09aa\u09a8\u09bf \u09aa\u09cd\u09b0\u09ac\u09c0\u09a3 \u09ae\u09cb\u09a1 \u09ac\u09a8\u09cd\u09a7 \u0995\u09b0\u09c7\u09a8 (\u0993\u0987 \u09b9\u09cb\u09ae\u09c7 \u09ac\u09be \u09b8\u09c7\u099f\u09bf\u0982\u09b8\u09c7)\u0964"],t.s)
