B.aZ5=s(["\u062a\u0627\u0628\u0639 \u0642\u0631\u0627\u0621\u0629 {1}","{1} \u067e\u0691\u06be\u0646\u0627 \u062c\u0627\u0631\u06cc \u0631\u06a9\u06be\u06cc\u06ba","{1} \u09aa\u09a1\u09bc\u09be \u099a\u09be\u09b2\u09bf\u09af\u09bc\u09c7 \u09af\u09be\u09a8"],t.s)
B.bsz=s(["\u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0645\u0639 \u0627\u0644\u062a\u0631\u062c\u0645\u0629 \u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629 \u0628\u062c\u0627\u0646\u0628\u0647.","\u0642\u0631\u0622\u0646\u060c \u0627\u0633 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0627\u0646\u06af\u0631\u06cc\u0632\u06cc \u062a\u0631\u062c\u0645\u06c1\u06d4","\u0995\u09c1\u09b0\u0986\u09a8, \u09aa\u09be\u09b6\u09c7 \u0987\u0982\u09b0\u09c7\u099c\u09bf \u0985\u09a8\u09c1\u09ac\u09be\u09a6\u09b8\u09b9\u0964"],t.s)
