B.aQW=s(["\u063a\u0637\u0627\u0621 \u0639\u0627\u062f\u064a \u0639\u0646\u062f \u062a\u0631\u0643 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0623\u0648 \u0627\u0644\u062a\u0628\u062f\u064a\u0644 \u0645\u0646\u0647\u060c \u0648\u0645\u062d\u0648 \u0645\u062d\u0627\u062f\u062b\u0627\u062a \u0647\u0627\u062f\u064a \u0648\u0648\u0635\u064a\u0629 \u0639\u0646\u062f \u0627\u0644\u0645\u063a\u0627\u062f\u0631\u0629\u060c \u0648\u0644\u0627 \u0646\u0635 \u0631\u0633\u0627\u0626\u0644 \u0641\u064a \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a\u060c \u0648\u0644\u0627 \u0634\u0627\u0634\u0629 \u062f\u0639\u0645 \u0639\u0646\u062f \u0641\u062a\u062d \u0627\u0644\u062a\u0637\u0628\u064a\u0642. \u0644\u0627 \u064a\u062e\u0641\u064a \u0633\u062c\u0644 \u0627\u0644\u0645\u062a\u0635\u0641\u062d \u0646\u0641\u0633\u0647 \u0648\u0644\u0627 \u0634\u0631\u064a\u0637 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0639\u0644\u0649 \u0627\u0644\u0648\u064a\u0628.","\u0627\u06cc\u067e \u0686\u06be\u0648\u0691\u0646\u06d2 \u06cc\u0627 \u0628\u062f\u0644\u0646\u06d2 \u067e\u0631 \u0633\u0627\u062f\u06c1 \u067e\u0631\u062f\u06c1\u060c \u062c\u0627\u0646\u06d2 \u067e\u0631 \u06c1\u0627\u062f\u06cc \u0627\u0648\u0631 \u0648\u0635\u06cc\u06c1 \u06a9\u06cc \u06af\u0641\u062a\u06af\u0648 \u0635\u0627\u0641\u060c \u0646\u0648\u0679\u06cc\u0641\u06a9\u06cc\u0634\u0646 \u0645\u06cc\u06ba \u067e\u06cc\u063a\u0627\u0645 \u06a9\u0627 \u0645\u062a\u0646 \u0646\u06c1\u06cc\u06ba\u060c \u0627\u0648\u0631 \u0627\u06cc\u067e \u06a9\u06be\u0644\u0646\u06d2 \u067e\u0631 \u0633\u067e\u0648\u0631\u0679 \u0627\u0633\u06a9\u0631\u06cc\u0646 \u0646\u06c1\u06cc\u06ba\u06d4 \u06cc\u06c1 \u0648\u06cc\u0628 \u067e\u0631 \u0628\u0631\u0627\u0624\u0632\u0631 \u06a9\u06cc \u0627\u067e\u0646\u06cc \u06c1\u0633\u0679\u0631\u06cc \u06cc\u0627 \u0627\u06cc\u0688\u0631\u06cc\u0633 \u0628\u0627\u0631 \u06a9\u0648 \u0646\u06c1\u06cc\u06ba \u0686\u06be\u067e\u0627\u062a\u0627\u06d4","\u0985\u09cd\u09af\u09be\u09aa \u099b\u09be\u09a1\u09bc\u09b2\u09c7 \u09ac\u09be \u09ac\u09a6\u09b2\u09be\u09b2\u09c7 \u09b8\u09be\u09a6\u09be\u09ae\u09be\u099f\u09be \u0986\u09ac\u09b0\u09a3, \u099a\u09b2\u09c7 \u0997\u09c7\u09b2\u09c7 \u09b9\u09be\u09a6\u09c0 \u0993 \u0993\u09af\u09bc\u09be\u09b8\u09bf\u09af\u09bc\u09be\u09b0 \u0995\u09a5\u09cb\u09aa\u0995\u09a5\u09a8 \u09ae\u09c1\u099b\u09c7 \u09af\u09be\u0993\u09af\u09bc\u09be, \u09a8\u09cb\u099f\u09bf\u09ab\u09bf\u0995\u09c7\u09b6\u09a8\u09c7 \u09ac\u09be\u09b0\u09cd\u09a4\u09be\u09b0 \u09b2\u09c7\u0996\u09be \u09a8\u09c7\u0987, \u098f\u09ac\u0982 \u0985\u09cd\u09af\u09be\u09aa \u0996\u09c1\u09b2\u09b2\u09c7 \u09b8\u09b9\u09be\u09af\u09bc\u09a4\u09be \u09aa\u09b0\u09cd\u09a6\u09be \u09a8\u09c7\u0987\u0964 \u0993\u09af\u09bc\u09c7\u09ac\u09c7 \u098f\u099f\u09bf \u09ac\u09cd\u09b0\u09be\u0989\u099c\u09be\u09b0\u09c7\u09b0 \u09a8\u09bf\u099c\u09c7\u09b0 \u0987\u09a4\u09bf\u09b9\u09be\u09b8 \u09ac\u09be \u09a0\u09bf\u0995\u09be\u09a8\u09be-\u09ac\u09be\u09b0 \u09b2\u09c1\u0995\u09be\u09af\u09bc \u09a8\u09be\u0964"],t.s)
B.bvj=s(["\u0632\u0631 \u0627\u0644\u062e\u0631\u0648\u062c \u0627\u0644\u0633\u0631\u064a\u0639","\u0641\u0648\u0631\u06cc \u0627\u062e\u0631\u0627\u062c \u06a9\u0627 \u0628\u0679\u0646","\u09a6\u09cd\u09b0\u09c1\u09a4 \u09ac\u09c7\u09b0\u09cb\u09a8\u09cb\u09b0 \u09ac\u09cb\u09a4\u09be\u09ae"],t.s)
B.by4=s(["\u064a\u0638\u0647\u0631 \u0641\u064a \u0634\u0627\u0634\u0627\u062a \u0627\u0644\u062f\u0639\u0645. \u064a\u0645\u062d\u0648 \u0627\u0644\u0645\u062d\u0627\u062f\u062b\u0629 \u0648\u064a\u063a\u0627\u062f\u0631 \u0641\u0648\u0631\u064b\u0627.","\u0633\u067e\u0648\u0631\u0679 \u0627\u0633\u06a9\u0631\u06cc\u0646\u0648\u06ba \u067e\u0631 \u062f\u06a9\u06be\u0627\u06cc\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4 \u06af\u0641\u062a\u06af\u0648 \u0635\u0627\u0641 \u06a9\u0631 \u06a9\u06d2 \u0641\u0648\u0631\u0627\u064b \u0646\u06a9\u0644 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4","\u09b8\u09b9\u09be\u09af\u09bc\u09a4\u09be \u09aa\u09b0\u09cd\u09a6\u09be\u09af\u09bc \u09a6\u09c7\u0996\u09be\u09a8\u09cb \u09b9\u09af\u09bc\u0964 \u0995\u09a5\u09cb\u09aa\u0995\u09a5\u09a8 \u09ae\u09c1\u099b\u09c7 \u09b8\u0999\u09cd\u0997\u09c7 \u09b8\u0999\u09cd\u0997\u09c7 \u09ac\u09c7\u09b0\u09bf\u09af\u09bc\u09c7 \u09af\u09be\u09af\u09bc\u0964"],t.s)
B.bge=s(["\u0632\u0631 \u0627\u0644\u062e\u0631\u0648\u062c \u0627\u0644\u0633\u0631\u064a\u0639 \u0639\u0644\u0649 \u0627\u0644\u064a\u0633\u0627\u0631","\u0641\u0648\u0631\u06cc \u0627\u062e\u0631\u0627\u062c \u06a9\u0627 \u0628\u0679\u0646 \u0628\u0627\u0626\u06cc\u06ba \u0637\u0631\u0641","\u09a6\u09cd\u09b0\u09c1\u09a4 \u09ac\u09c7\u09b0\u09cb\u09a8\u09cb\u09b0 \u09ac\u09cb\u09a4\u09be\u09ae \u09ac\u09be\u09ae\u09c7"],t.s)
B.bla=s(["\u0639\u0646\u062f \u0627\u0644\u0625\u064a\u0642\u0627\u0641 \u064a\u0643\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u064a\u0645\u064a\u0646.","\u0628\u0646\u062f \u06c1\u0648 \u062a\u0648 \u062f\u0627\u0626\u06cc\u06ba \u0637\u0631\u0641 \u0631\u06c1\u062a\u0627 \u06c1\u06d2\u06d4","\u09ac\u09a8\u09cd\u09a7 \u09a5\u09be\u0995\u09b2\u09c7 \u09a1\u09be\u09a8\u09c7 \u09a5\u09be\u0995\u09c7\u0964"],t.s)
B.bfQ=s(["\u0627\u0644\u0643\u0644\u0645\u0629 \u0627\u0644\u0622\u0645\u0646\u0629","\u0645\u062d\u0641\u0648\u0638 \u0644\u0641\u0638","\u09a8\u09bf\u09b0\u09be\u09aa\u09a6 \u09b6\u09ac\u09cd\u09a6"],t.s)
B.bta=s(["\u063a\u064a\u0631 \u0645\u062d\u062f\u062f\u0629. \u0627\u0643\u062a\u0628 \u0643\u0644\u0645\u062a\u0643 \u0641\u064a \u0647\u0627\u062f\u064a \u0644\u0645\u062d\u0648 \u0627\u0644\u0645\u062d\u0627\u062f\u062b\u0629 \u0648\u0627\u0644\u0645\u063a\u0627\u062f\u0631\u0629 \u0641\u0648\u0631\u064b\u0627.","\u0645\u0642\u0631\u0631 \u0646\u06c1\u06cc\u06ba\u06d4 \u06af\u0641\u062a\u06af\u0648 \u0635\u0627\u0641 \u06a9\u0631 \u06a9\u06d2 \u0641\u0648\u0631\u0627\u064b \u0646\u06a9\u0644\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u06c1\u0627\u062f\u06cc \u0645\u06cc\u06ba \u0627\u067e\u0646\u0627 \u0644\u0641\u0638 \u0644\u06a9\u06be\u06cc\u06ba\u06d4","\u09a0\u09bf\u0995 \u0995\u09b0\u09be \u09a8\u09c7\u0987\u0964 \u0995\u09a5\u09cb\u09aa\u0995\u09a5\u09a8 \u09ae\u09c1\u099b\u09c7 \u09b8\u0999\u09cd\u0997\u09c7 \u09b8\u0999\u09cd\u0997\u09c7 \u09ac\u09c7\u09b0\u09cb\u09a4\u09c7 \u09b9\u09be\u09a6\u09c0\u09a4\u09c7 \u0986\u09aa\u09a8\u09be\u09b0 \u09b6\u09ac\u09cd\u09a6 \u09b2\u09bf\u0996\u09c1\u09a8\u0964"],t.s)
B.bxv=s(["\u0645\u062d\u062f\u062f\u0629 \u0644\u0647\u0630\u0647 \u0627\u0644\u0632\u064a\u0627\u0631\u0629 \u0641\u0642\u0637. \u0639\u0644\u0649 \u0627\u0644\u0648\u064a\u0628 \u062a\u064f\u0646\u0633\u0649 \u0639\u0646\u062f \u0625\u063a\u0644\u0627\u0642 \u0627\u0644\u0635\u0641\u062d\u0629 \u0623\u0648 \u0625\u0639\u0627\u062f\u0629 \u062a\u062d\u0645\u064a\u0644\u0647\u0627\u060c \u0641\u062d\u062f\u0651\u062f\u0647\u0627 \u0645\u062c\u062f\u062f\u064b\u0627 \u0641\u064a \u0627\u0644\u0645\u0631\u0629 \u0627\u0644\u0642\u0627\u062f\u0645\u0629. \u0643\u062a\u0627\u0628\u062a\u0647\u0627 \u0641\u064a \u0647\u0627\u062f\u064a \u062a\u0645\u062d\u0648 \u0627\u0644\u0645\u062d\u0627\u062f\u062b\u0629 \u0648\u062a\u063a\u0627\u062f\u0631 \u0641\u0648\u0631\u064b\u0627.","\u0635\u0631\u0641 \u0627\u0633 \u0648\u0632\u0679 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0645\u0642\u0631\u0631\u06d4 \u0648\u06cc\u0628 \u067e\u0631 \u0635\u0641\u062d\u06c1 \u0628\u0646\u062f \u06cc\u0627 \u0631\u06cc \u0644\u0648\u0688 \u06c1\u0648\u0646\u06d2 \u067e\u0631 \u0628\u06be\u0644\u0627 \u062f\u06cc\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u060c \u0627\u0633 \u0644\u06cc\u06d2 \u0627\u06af\u0644\u06cc \u0628\u0627\u0631 \u062f\u0648\u0628\u0627\u0631\u06c1 \u0645\u0642\u0631\u0631 \u06a9\u0631\u06cc\u06ba\u06d4 \u06c1\u0627\u062f\u06cc \u0645\u06cc\u06ba \u0627\u0633\u06d2 \u0644\u06a9\u06be\u0646\u06d2 \u0633\u06d2 \u06af\u0641\u062a\u06af\u0648 \u0635\u0627\u0641 \u06c1\u0648 \u062c\u0627\u062a\u06cc \u06c1\u06d2 \u0627\u0648\u0631 \u0641\u0648\u0631\u0627\u064b \u0646\u06a9\u0644 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4","\u09b6\u09c1\u09a7\u09c1 \u098f\u0987 \u09b8\u09ab\u09b0\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u09a0\u09bf\u0995 \u0995\u09b0\u09be\u0964 \u0993\u09af\u09bc\u09c7\u09ac\u09c7 \u09aa\u09be\u09a4\u09be \u09ac\u09a8\u09cd\u09a7 \u09ac\u09be \u09b0\u09bf\u09b2\u09cb\u09a1 \u09b9\u09b2\u09c7 \u098f\u099f\u09bf \u09ad\u09c1\u09b2\u09c7 \u09af\u09be\u09af\u09bc, \u09a4\u09be\u0987 \u09aa\u09b0\u09c7\u09b0 \u09ac\u09be\u09b0 \u0986\u09ac\u09be\u09b0 \u09a0\u09bf\u0995 \u0995\u09b0\u09c1\u09a8\u0964 \u09b9\u09be\u09a6\u09c0\u09a4\u09c7 \u098f\u099f\u09bf \u09b2\u09bf\u0996\u09b2\u09c7 \u099a\u09cd\u09af\u09be\u099f \u09ae\u09c1\u099b\u09c7 \u09b8\u0999\u09cd\u0997\u09c7 \u09b8\u0999\u09cd\u0997\u09c7 \u09ac\u09c7\u09b0\u09bf\u09af\u09bc\u09c7 \u09af\u09be\u09af\u09bc\u0964"],t.s)
B.b9U=s(["\u0645\u062d\u062f\u062f\u0629. \u0643\u062a\u0627\u0628\u062a\u0647\u0627 \u0641\u064a \u0647\u0627\u062f\u064a \u062a\u0645\u062d\u0648 \u0627\u0644\u0645\u062d\u0627\u062f\u062b\u0629 \u0648\u062a\u063a\u0627\u062f\u0631 \u0641\u0648\u0631\u064b\u0627.","\u0645\u0642\u0631\u0631\u06d4 \u06c1\u0627\u062f\u06cc \u0645\u06cc\u06ba \u0627\u0633\u06d2 \u0644\u06a9\u06be\u0646\u06d2 \u0633\u06d2 \u06af\u0641\u062a\u06af\u0648 \u0635\u0627\u0641 \u06c1\u0648 \u062c\u0627\u062a\u06cc \u06c1\u06d2 \u0627\u0648\u0631 \u0641\u0648\u0631\u0627\u064b \u0646\u06a9\u0644 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4","\u09a0\u09bf\u0995 \u0995\u09b0\u09be \u0986\u099b\u09c7\u0964 \u09b9\u09be\u09a6\u09c0\u09a4\u09c7 \u098f\u099f\u09bf \u09b2\u09bf\u0996\u09b2\u09c7 \u099a\u09cd\u09af\u09be\u099f \u09ae\u09c1\u099b\u09c7 \u09b8\u0999\u09cd\u0997\u09c7 \u09b8\u0999\u09cd\u0997\u09c7 \u09ac\u09c7\u09b0\u09bf\u09af\u09bc\u09c7 \u09af\u09be\u09af\u09bc\u0964"],t.s)
B.b3a=s(["\u0644\u0627 \u064a\u0645\u0643\u0646 \u062a\u063a\u064a\u064a\u0631 \u0627\u0633\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0639\u0644\u0649 \u0634\u0627\u0634\u062a\u0643 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 \u0645\u0646 \u062f\u0627\u062e\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642. \u0647\u0630\u0627 \u0642\u064a\u062f \u0645\u0646 \u0627\u0644\u0647\u0627\u062a\u0641.","\u0622\u067e \u06a9\u06cc \u06c1\u0648\u0645 \u0627\u0633\u06a9\u0631\u06cc\u0646 \u067e\u0631 \u0627\u06cc\u067e \u06a9\u0627 \u0646\u0627\u0645 \u0627\u06cc\u067e \u06a9\u06d2 \u0627\u0646\u062f\u0631 \u0633\u06d2 \u0646\u06c1\u06cc\u06ba \u0628\u062f\u0644\u0627 \u062c\u0627 \u0633\u06a9\u062a\u0627\u06d4 \u06cc\u06c1 \u0641\u0648\u0646 \u06a9\u06cc \u062d\u062f \u06c1\u06d2\u06d4","\u0986\u09aa\u09a8\u09be\u09b0 \u09b9\u09cb\u09ae \u09b8\u09cd\u0995\u09cd\u09b0\u09bf\u09a8\u09c7 \u0985\u09cd\u09af\u09be\u09aa\u09c7\u09b0 \u09a8\u09be\u09ae \u0985\u09cd\u09af\u09be\u09aa\u09c7\u09b0 \u09ad\u09c7\u09a4\u09b0 \u09a5\u09c7\u0995\u09c7 \u09ac\u09a6\u09b2\u09be\u09a8\u09cb \u09af\u09be\u09af\u09bc \u09a8\u09be\u0964 \u098f\u099f\u09bf \u09ab\u09cb\u09a8\u09c7\u09b0 \u09b8\u09c0\u09ae\u09be\u09ac\u09a6\u09cd\u09a7\u09a4\u09be\u0964"],t.s)
B.b6q=s(["\u0627\u0644\u0644\u063a\u0629","\u0632\u0628\u0627\u0646","\u09ad\u09be\u09b7\u09be"],t.s)
B.bp4=s(["\u0644\u063a\u0629 \u062e\u0637\u0648\u0637 \u0627\u0644\u062f\u0639\u0645","\u0633\u067e\u0648\u0631\u0679 \u0644\u0627\u0626\u0646\u0648\u06ba \u06a9\u06cc \u0632\u0628\u0627\u0646","\u09b8\u09b9\u09be\u09af\u09bc\u09a4\u09be \u09b2\u09be\u0987\u09a8\u09c7\u09b0 \u09ad\u09be\u09b7\u09be"],t.s)
B.b4V=s(["\u0635\u064a\u0627\u063a\u0629 \u0627\u0644\u0637\u0648\u0627\u0631\u0626 \u0648\u062e\u0637\u0648\u0637 \u0627\u0644\u0645\u0633\u0627\u0639\u062f\u0629 \u0628\u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0623\u0631\u062f\u064a\u0629 \u0648\u0627\u0644\u0628\u0646\u063a\u0627\u0644\u064a\u0629 \u0645\u0633\u0648\u062f\u0629 \u0622\u0644\u064a\u0629 \u0644\u0645 \u064a\u0642\u0631\u0623\u0647\u0627 \u0637\u0628\u064a\u0628 \u0646\u0641\u0633\u064a \u0646\u0627\u0637\u0642 \u0623\u0635\u0644\u064a \u0628\u0639\u062f. \u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629 \u0647\u064a \u0627\u0644\u0623\u0648\u0641\u0631.","\u06c1\u0646\u06af\u0627\u0645\u06cc \u0635\u0648\u0631\u062a \u0627\u0648\u0631 \u06c1\u06cc\u0644\u067e \u0644\u0627\u0626\u0646\u0648\u06ba \u06a9\u06d2 \u0639\u0631\u0628\u06cc\u060c \u0627\u0631\u062f\u0648 \u0627\u0648\u0631 \u0628\u0646\u06af\u0644\u06c1 \u0627\u0644\u0641\u0627\u0638 \u0645\u0634\u06cc\u0646 \u0633\u06d2 \u062a\u06cc\u0627\u0631 \u06a9\u0631\u062f\u06c1 \u0645\u0633\u0648\u062f\u06c1 \u06c1\u06cc\u06ba \u0627\u0648\u0631 \u0627\u0628\u06be\u06cc \u06a9\u0633\u06cc \u0645\u0627\u062f\u0631\u06cc \u0632\u0628\u0627\u0646 \u0628\u0648\u0644\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0645\u0639\u0627\u0644\u062c \u0646\u06d2 \u0646\u06c1\u06cc\u06ba \u067e\u0691\u06be\u06d2\u06d4 \u0627\u0646\u06af\u0631\u06cc\u0632\u06cc \u0645\u06cc\u06ba \u0633\u0628 \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u06c1\u06d2\u06d4","\u099c\u09b0\u09c1\u09b0\u09bf \u0985\u09ac\u09b8\u09cd\u09a5\u09be \u0993 \u09b9\u09c7\u09b2\u09cd\u09aa\u09b2\u09be\u0987\u09a8\u09c7\u09b0 \u0986\u09b0\u09ac\u09bf, \u0989\u09b0\u09cd\u09a6\u09c1 \u0993 \u09ac\u09be\u0982\u09b2\u09be \u09b6\u09ac\u09cd\u09a6\u099a\u09af\u09bc\u09a8 \u098f\u0995\u099f\u09bf \u09af\u09be\u09a8\u09cd\u09a4\u09cd\u09b0\u09bf\u0995 \u0996\u09b8\u09a1\u09bc\u09be \u098f\u09ac\u0982 \u098f\u0996\u09a8\u0993 \u0995\u09cb\u09a8\u09cb \u09ae\u09be\u09a4\u09c3\u09ad\u09be\u09b7\u09c0 \u099a\u09bf\u0995\u09bf\u09ce\u09b8\u0995 \u09aa\u09a1\u09bc\u09c7\u09a8\u09a8\u09bf\u0964 \u0987\u0982\u09b0\u09c7\u099c\u09bf\u09a4\u09c7 \u09b8\u09ac\u099a\u09c7\u09af\u09bc\u09c7 \u09ac\u09c7\u09b6\u09bf \u0986\u099b\u09c7\u0964"],t.s)
B.boQ=s(["\u0627\u062a\u0628\u0639 \u0644\u063a\u0629 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 (\u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a)","\u0627\u06cc\u067e \u06a9\u06cc \u0632\u0628\u0627\u0646 \u06a9\u06d2 \u0645\u0637\u0627\u0628\u0642 (\u0688\u06cc\u0641\u0627\u0644\u0679)","\u0985\u09cd\u09af\u09be\u09aa\u09c7\u09b0 \u09ad\u09be\u09b7\u09be \u0985\u09a8\u09c1\u09b8\u09b0\u09a3 \u0995\u09b0\u09c1\u09a8 (\u09a1\u09bf\u09ab\u09b2\u09cd\u099f)"],t.s)
