B.brb=s(["\u0644\u0627 \u064a\u064f\u062d\u0641\u0638 \u0634\u064a\u0621 \u0645\u0645\u0627 \u062a\u0642\u0631\u0624\u0647 \u0647\u0646\u0627. \u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u062d\u0627\u062a \u0644\u064a\u0633\u062a \u0637\u0628\u064a\u0628\u064b\u0627 \u0648\u0644\u0627 \u0645\u0631\u0634\u062f\u064b\u0627 \u0646\u0641\u0633\u064a\u064b\u0627 \u0648\u0644\u0627 \u0639\u0627\u0644\u0645\u064b\u0627. \u0625\u0646\u0647\u0627 \u062a\u062f\u0644\u0651\u0643 \u0639\u0644\u0649 \u0645\u0646 \u0647\u0645 \u0643\u0630\u0644\u0643.","\u06cc\u06c1\u0627\u06ba \u062c\u0648 \u0622\u067e \u067e\u0691\u06be\u062a\u06d2 \u06c1\u06cc\u06ba \u0648\u06c1 \u0645\u062d\u0641\u0648\u0638 \u0646\u06c1\u06cc\u06ba \u06c1\u0648\u062a\u0627\u06d4 \u06cc\u06c1 \u0635\u0641\u062d\u0627\u062a \u0688\u0627\u06a9\u0679\u0631\u060c \u0645\u0634\u06cc\u0631 \u06cc\u0627 \u0639\u0627\u0644\u0645 \u0646\u06c1\u06cc\u06ba \u06c1\u06cc\u06ba\u06d4 \u06cc\u06c1 \u0627\u0646 \u0644\u0648\u06af\u0648\u06ba \u06a9\u06cc \u0637\u0631\u0641 \u0631\u06c1\u0646\u0645\u0627\u0626\u06cc \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba \u062c\u0648 \u06c1\u06cc\u06ba\u06d4","\u098f\u0996\u09be\u09a8\u09c7 \u0986\u09aa\u09a8\u09bf \u09af\u09be \u09aa\u09a1\u09bc\u09c7\u09a8 \u09a4\u09be \u09b8\u0982\u09b0\u0995\u09cd\u09b7\u09bf\u09a4 \u09b9\u09af\u09bc \u09a8\u09be\u0964 \u098f\u0987 \u09aa\u09be\u09a4\u09be\u0997\u09c1\u09b2\u09cb \u099a\u09bf\u0995\u09bf\u09ce\u09b8\u0995, \u0995\u09be\u0989\u09a8\u09cd\u09b8\u09c7\u09b2\u09b0 \u09ac\u09be \u0986\u09b2\u09c7\u09ae \u09a8\u09af\u09bc\u0964 \u098f\u0997\u09c1\u09b2\u09cb \u09b8\u09c7\u0987 \u09ae\u09be\u09a8\u09c1\u09b7\u09a6\u09c7\u09b0 \u09a6\u09bf\u0995\u09c7 \u09a8\u09bf\u09b0\u09cd\u09a6\u09c7\u09b6 \u0995\u09b0\u09c7 \u09af\u09be\u0981\u09b0\u09be \u09a4\u09be\u0964"],t.s)
B.bm5=s(["\u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u062d\u0629 \u063a\u064a\u0631 \u0645\u0648\u062c\u0648\u062f\u0629.","\u0648\u06c1 \u0635\u0641\u062d\u06c1 \u06cc\u06c1\u0627\u06ba \u0646\u06c1\u06cc\u06ba \u06c1\u06d2\u06d4","\u09b8\u09c7\u0987 \u09aa\u09be\u09a4\u09be\u099f\u09bf \u098f\u0996\u09be\u09a8\u09c7 \u09a8\u09c7\u0987\u0964"],t.s)
B.aP9=s(["\u0625\u0630\u0627 \u0643\u0646\u062a \u0641\u064a \u062e\u0637\u0631 \u0627\u0644\u0622\u0646 \u0641\u0627\u062a\u0635\u0644 \u0628\u0631\u0642\u0645 \u0627\u0644\u0637\u0648\u0627\u0631\u0626 \u0627\u0644\u0645\u062d\u0644\u064a. \u0648\u0625\u0646 \u0644\u0645 \u064a\u0643\u0646 \u0627\u0644\u062a\u062d\u062f\u062b \u0622\u0645\u0646\u064b\u0627 \u0641\u063a\u0627\u062f\u0631 \u0647\u0630\u0647 \u0627\u0644\u0634\u0627\u0634\u0629 \u0628\u0632\u0631 \xab\u0627\u062e\u0631\u062c \u0627\u0644\u0622\u0646\xbb \u0623\u0639\u0644\u0627\u0647. \u0644\u0633\u062a \u0645\u0636\u0637\u0631\u064b\u0627 \u0625\u0644\u0649 \u0627\u062a\u062e\u0627\u0630 \u0623\u064a \u0642\u0631\u0627\u0631 \u0627\u0644\u0644\u064a\u0644\u0629.","\u0627\u06af\u0631 \u0622\u067e \u0627\u0628\u06be\u06cc \u062e\u0637\u0631\u06d2 \u0645\u06cc\u06ba \u06c1\u06cc\u06ba \u062a\u0648 \u0627\u067e\u0646\u06d2 \u0645\u0642\u0627\u0645\u06cc \u0627\u06cc\u0645\u0631\u062c\u0646\u0633\u06cc \u0646\u0645\u0628\u0631 \u067e\u0631 \u06a9\u0627\u0644 \u06a9\u0631\u06cc\u06ba\u06d4 \u0627\u06af\u0631 \u0628\u0627\u062a \u06a9\u0631\u0646\u0627 \u0645\u062d\u0641\u0648\u0638 \u0646\u06c1 \u06c1\u0648 \u062a\u0648 \u0627\u0648\u067e\u0631 \xab\u0627\u0628\u06be\u06cc \u0646\u06a9\u0644\u06cc\u06ba\xbb \u0633\u06d2 \u06cc\u06c1 \u0627\u0633\u06a9\u0631\u06cc\u0646 \u0686\u06be\u0648\u0691 \u062f\u06cc\u06ba\u06d4 \u0622\u067e \u06a9\u0648 \u0622\u062c \u0631\u0627\u062a \u06a9\u0686\u06be \u0637\u06d2 \u06a9\u0631\u0646\u06d2 \u06a9\u06cc \u0636\u0631\u0648\u0631\u062a \u0646\u06c1\u06cc\u06ba\u06d4","\u0986\u09aa\u09a8\u09bf \u098f\u0996\u09a8\u0987 \u09ac\u09bf\u09aa\u09a6\u09c7 \u09a5\u09be\u0995\u09b2\u09c7 \u0986\u09aa\u09a8\u09be\u09b0 \u09b8\u09cd\u09a5\u09be\u09a8\u09c0\u09af\u09bc \u099c\u09b0\u09c1\u09b0\u09bf \u09a8\u09ae\u09cd\u09ac\u09b0\u09c7 \u09ab\u09cb\u09a8 \u0995\u09b0\u09c1\u09a8\u0964 \u0995\u09a5\u09be \u09ac\u09b2\u09be \u09a8\u09bf\u09b0\u09be\u09aa\u09a6 \u09a8\u09be \u09b9\u09b2\u09c7 \u0989\u09aa\u09b0\u09c7\u09b0 \xab\u098f\u0996\u09a8\u0987 \u09ac\u09c7\u09b0\u09cb\u09a8\xbb \u09a6\u09bf\u09af\u09bc\u09c7 \u098f\u0987 \u09aa\u09b0\u09cd\u09a6\u09be \u099b\u09be\u09a1\u09bc\u09c1\u09a8\u0964 \u0986\u099c \u09b0\u09be\u09a4\u09c7 \u0986\u09aa\u09a8\u09be\u0995\u09c7 \u0995\u09bf\u099b\u09c1\u0987 \u09a0\u09bf\u0995 \u0995\u09b0\u09a4\u09c7 \u09b9\u09ac\u09c7 \u09a8\u09be\u0964"],t.s)
B.bzs=s(["\u0635\u064a\u0627\u063a\u0629 \u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u062d\u0629 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d\u0629 \u0627\u0644\u0622\u0646. \u0648\u062e\u0637\u0648\u0637 \u0627\u0644\u0645\u0633\u0627\u0639\u062f\u0629 \u0623\u062f\u0646\u0627\u0647 \u0645\u0627 \u0632\u0627\u0644\u062a \u0645\u0648\u062c\u0648\u062f\u0629.","\u0627\u0633 \u0635\u0641\u062d\u06d2 \u06a9\u06d2 \u0627\u0644\u0641\u0627\u0638 \u0627\u0628\u06be\u06cc \u062f\u0633\u062a\u06cc\u0627\u0628 \u0646\u06c1\u06cc\u06ba\u06d4 \u0646\u06cc\u0686\u06d2 \u06c1\u06cc\u0644\u067e \u0644\u0627\u0626\u0646\u06cc\u06ba \u0627\u0628 \u0628\u06be\u06cc \u0645\u0648\u062c\u0648\u062f \u06c1\u06cc\u06ba\u06d4","\u098f\u0987 \u09aa\u09be\u09a4\u09be\u09b0 \u09b6\u09ac\u09cd\u09a6\u099a\u09af\u09bc\u09a8 \u098f\u0996\u09a8 \u09aa\u09be\u0993\u09af\u09bc\u09be \u09af\u09be\u099a\u09cd\u099b\u09c7 \u09a8\u09be\u0964 \u09a8\u09bf\u099a\u09c7\u09b0 \u09b9\u09c7\u09b2\u09cd\u09aa\u09b2\u09be\u0987\u09a8\u0997\u09c1\u09b2\u09cb \u098f\u0996\u09a8\u0993 \u0986\u099b\u09c7\u0964"],t.s)
B.b63=s(["\u0627\u0628\u062f\u0623 \u0645\u0646 \u0647\u0646\u0627","\u06cc\u06c1\u0627\u06ba \u0633\u06d2 \u0634\u0631\u0648\u0639 \u06a9\u0631\u06cc\u06ba","\u098f\u0996\u09be\u09a8 \u09a5\u09c7\u0995\u09c7 \u09b6\u09c1\u09b0\u09c1 \u0995\u09b0\u09c1\u09a8"],t.s)
