B.aWm=s(["\u0645\u0646 \u0627\u0644\u062c\u064a\u062f \u0623\u0646 \u062a\u0639\u0631\u0641","\u062c\u0627\u0646\u0646\u0627 \u0627\u0686\u06be\u0627 \u06c1\u06d2","\u099c\u09be\u09a8\u09be \u09ad\u09be\u09b2\u09cb"],t.s)
B.b6Z=s(["\u062e\u0637\u0648\u0629 \u0635\u063a\u064a\u0631\u0629","\u0627\u06cc\u06a9 \u0686\u06be\u0648\u0679\u0627 \u0642\u062f\u0645","\u098f\u0995\u099f\u09bf \u099b\u09cb\u099f \u09a7\u09be\u09aa"],t.s)
B.b1Y=s(["\u0644\u0644\u0639\u0627\u0626\u0644\u0629 \u0648\u0627\u0644\u0623\u0635\u062f\u0642\u0627\u0621","\u062e\u0627\u0646\u062f\u0627\u0646 \u0627\u0648\u0631 \u062f\u0648\u0633\u062a\u0648\u06ba \u06a9\u06d2 \u0644\u06cc\u06d2","\u09aa\u09b0\u09bf\u09ac\u09be\u09b0 \u0993 \u09ac\u09a8\u09cd\u09a7\u09c1\u09a6\u09c7\u09b0 \u099c\u09a8\u09cd\u09af"],t.s)
B.b4Q=s(["\u0623\u0634\u062e\u0627\u0635 \u062a\u0644\u062c\u0623 \u0625\u0644\u064a\u0647\u0645","\u062c\u0646 \u06a9\u06cc \u0637\u0631\u0641 \u0631\u062c\u0648\u0639 \u06a9\u0631\u06cc\u06ba","\u09af\u09be\u0981\u09a6\u09c7\u09b0 \u0995\u09be\u099b\u09c7 \u09af\u09c7\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7\u09a8"],t.s)
