B.beh=s(["\u0647\u0630\u0627 \u0627\u0644\u0631\u062f \u0628\u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629 \u0641\u0642\u0637 \u062d\u0627\u0644\u064a\u064b\u0627 \u0644\u0623\u0646 \u062a\u0631\u062c\u0645\u062a\u0647 \u0644\u0645 \u064a\u0631\u0627\u062c\u0639\u0647\u0627 \u0645\u062a\u062d\u062f\u062b \u0623\u0635\u0644\u064a. \u0625\u0630\u0627 \u0643\u0646\u062a \u0641\u064a \u062e\u0637\u0631 \u0641\u0627\u062a\u0635\u0644 \u0628\u0631\u0642\u0645 \u0627\u0644\u0637\u0648\u0627\u0631\u0626 \u0627\u0644\u0645\u062d\u0644\u064a.","\u06cc\u06c1 \u062c\u0648\u0627\u0628 \u0641\u06cc \u0627\u0644\u062d\u0627\u0644 \u0635\u0631\u0641 \u0627\u0646\u06af\u0631\u06cc\u0632\u06cc \u0645\u06cc\u06ba \u06c1\u06d2 \u06a9\u06cc\u0648\u0646\u06a9\u06c1 \u0627\u0633 \u06a9\u0627 \u062a\u0631\u062c\u0645\u06c1 \u06a9\u0633\u06cc \u0645\u0627\u062f\u0631\u06cc \u0632\u0628\u0627\u0646 \u0628\u0648\u0644\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0646\u06d2 \u0646\u06c1\u06cc\u06ba \u062c\u0627\u0646\u0686\u0627\u06d4 \u0627\u06af\u0631 \u0622\u067e \u062e\u0637\u0631\u06d2 \u0645\u06cc\u06ba \u06c1\u06cc\u06ba \u062a\u0648 \u0627\u067e\u0646\u06d2 \u0645\u0642\u0627\u0645\u06cc \u0627\u06cc\u0645\u0631\u062c\u0646\u0633\u06cc \u0646\u0645\u0628\u0631 \u067e\u0631 \u06a9\u0627\u0644 \u06a9\u0631\u06cc\u06ba\u06d4","\u098f\u0987 \u0989\u09a4\u09cd\u09a4\u09b0 \u0986\u09aa\u09be\u09a4\u09a4 \u09b6\u09c1\u09a7\u09c1 \u0987\u0982\u09b0\u09c7\u099c\u09bf\u09a4\u09c7, \u0995\u09be\u09b0\u09a3 \u098f\u09b0 \u0985\u09a8\u09c1\u09ac\u09be\u09a6 \u0995\u09cb\u09a8\u09cb \u09ae\u09be\u09a4\u09c3\u09ad\u09be\u09b7\u09c0 \u09af\u09be\u099a\u09be\u0987 \u0995\u09b0\u09c7\u09a8\u09a8\u09bf\u0964 \u0986\u09aa\u09a8\u09bf \u09ac\u09bf\u09aa\u09a6\u09c7 \u09a5\u09be\u0995\u09b2\u09c7 \u0986\u09aa\u09a8\u09be\u09b0 \u09b8\u09cd\u09a5\u09be\u09a8\u09c0\u09af\u09bc \u099c\u09b0\u09c1\u09b0\u09bf \u09a8\u09ae\u09cd\u09ac\u09b0\u09c7 \u09ab\u09cb\u09a8 \u0995\u09b0\u09c1\u09a8\u0964"],t.s)
B.baW=s(["\u0627\u0644\u0625\u0634\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u0631\u062c\u0639\u064a\u0629","\u0628\u06a9 \u0645\u0627\u0631\u06a9\u0633","\u09ac\u09c1\u0995\u09ae\u09be\u09b0\u09cd\u0995"],t.s)
