B.b1y=s(["\u0627\u0644\u0639\u0631\u0628\u064a\u0629\u060c \u062b\u0645 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0628\u0627\u0644\u062d\u0631\u0648\u0641 \u0627\u0644\u0644\u0627\u062a\u064a\u0646\u064a\u0629\u060c \u062b\u0645 \u0627\u0644\u0645\u0639\u0646\u0649\u060c \u062f\u0627\u0626\u0645\u064b\u0627.","\u0639\u0631\u0628\u06cc\u060c \u067e\u06be\u0631 \u0644\u0627\u0637\u06cc\u0646\u06cc \u062d\u0631\u0648\u0641 \u0645\u06cc\u06ba \u0639\u0631\u0628\u06cc\u060c \u067e\u06be\u0631 \u0645\u0637\u0644\u0628\u060c \u06c1\u0645\u06cc\u0634\u06c1\u06d4","\u0986\u09b0\u09ac\u09bf, \u09a4\u09be\u09b0\u09aa\u09b0 \u09b2\u09cd\u09af\u09be\u099f\u09bf\u09a8 \u09b9\u09b0\u09ab\u09c7 \u0986\u09b0\u09ac\u09bf, \u09a4\u09be\u09b0\u09aa\u09b0 \u0985\u09b0\u09cd\u09a5, \u09b8\u09ac\u09b8\u09ae\u09af\u09bc\u0964"],t.s)
B.bk9=s(["\u0645\u062b\u0644 \u0625\u0638\u0647\u0627\u0631 \u0643\u0644 \u0634\u064a\u0621\u060c \u0644\u0643\u0646 \u0627\u0644\u062d\u0631\u0648\u0641 \u0627\u0644\u0644\u0627\u062a\u064a\u0646\u064a\u0629 \u062a\u062a\u0631\u0627\u062c\u0639 \u062e\u0644\u0641 \u0632\u0631 \u0627\u0642\u0631\u0623\u0647 \u0644\u0645\u0627 \u062a\u0639\u0631\u0641\u0647.","\u0633\u0628 \u06a9\u0686\u06be \u062f\u06a9\u06be\u0627\u0626\u06cc\u06ba \u06a9\u06cc \u0637\u0631\u062d\u060c \u0645\u06af\u0631 \u062c\u0648 \u0622\u067e \u062c\u0627\u0646\u062a\u06d2 \u06c1\u06cc\u06ba \u0627\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0644\u0627\u0637\u06cc\u0646\u06cc \u062d\u0631\u0648\u0641 \u067e\u0691\u06be\u06cc\u06ba \u06a9\u06d2 \u0628\u0679\u0646 \u06a9\u06d2 \u067e\u06cc\u0686\u06be\u06d2 \u0686\u0644\u06d2 \u062c\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4","\u09b8\u09ac \u09a6\u09c7\u0996\u09be\u09a8-\u098f\u09b0 \u09ae\u09a4\u09cb, \u09a4\u09ac\u09c7 \u09af\u09be \u0986\u09aa\u09a8\u09bf \u099c\u09be\u09a8\u09c7\u09a8 \u09a4\u09be\u09b0 \u09b2\u09cd\u09af\u09be\u099f\u09bf\u09a8 \u09b9\u09b0\u09ab \u09aa\u09a1\u09bc\u09c1\u09a8 \u09ac\u09cb\u09a4\u09be\u09ae\u09c7\u09b0 \u09aa\u09c7\u099b\u09a8\u09c7 \u09b8\u09b0\u09c7 \u09af\u09be\u09af\u09bc\u0964"],t.s)
B.b_c=s(["\u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0645\u0639\u0646\u0649. \u0627\u0644\u062d\u0631\u0648\u0641 \u0627\u0644\u0644\u0627\u062a\u064a\u0646\u064a\u0629 \u0639\u0644\u0649 \u0628\u0639\u062f \u0646\u0642\u0631\u0629.","\u0639\u0631\u0628\u06cc \u0627\u0648\u0631 \u0645\u0637\u0644\u0628\u06d4 \u0644\u0627\u0637\u06cc\u0646\u06cc \u062d\u0631\u0648\u0641 \u0627\u06cc\u06a9 \u0679\u06cc\u067e \u06a9\u06cc \u062f\u0648\u0631\u06cc \u067e\u0631 \u06c1\u06cc\u06ba\u06d4","\u0986\u09b0\u09ac\u09bf \u0993 \u0985\u09b0\u09cd\u09a5\u0964 \u09b2\u09cd\u09af\u09be\u099f\u09bf\u09a8 \u09b9\u09b0\u09ab \u098f\u0995 \u099f\u09cd\u09af\u09be\u09aa \u09a6\u09c2\u09b0\u09c7\u0964"],t.s)
